function moon(g,palette=['#bc6667','#77363b','#d37d7a']){
 const surface=new THREE.SphereGeometry(.457,40,28);
 const vertices=surface.attributes.position;
 const craters=[[.43,.25,.87,.25],[-.12,-.26,.96,.24],[-.56,.31,.77,.16],[.33,-.47,.82,.136],
  [.23,.74,.65,.14],[-.17,.42,-.89,.22],[.44,-.46,-.78,.20],[-.9,-.27,.32,.18]]
  .map(([x,y,z,r])=>[new THREE.Vector3(x,y,z).normalize(),r]);
 const tones=new Float32Array(vertices.count*3);
 const [base,pit,lip]=palette.map(color=>new THREE.Color(color));
 const point=new THREE.Vector3(),tint=new THREE.Color();
 for(let i=0;i<vertices.count;i++){
  point.fromBufferAttribute(vertices,i).normalize();
  let depth=0,rim=0;
  for(const [axis,radius] of craters){
   const d=point.distanceTo(axis)/radius;
   depth=Math.max(depth,Math.max(0,1-d*d));
   rim=Math.max(rim,Math.max(0,1-Math.abs(d-.94)*6));
  }
  const grain=Math.sin(point.x*145)*Math.cos(point.z*119)*.005;
  const r=.45-.045*depth+.018*rim+grain;
  vertices.setXYZ(i,point.x*r,point.y*r,point.z*r);
  tint.copy(base).lerp(pit,depth*.72).lerp(lip,rim*.51).toArray(tones,i*3);
 }
 surface.setAttribute('color',new THREE.BufferAttribute(tones,3));
 surface.computeVertexNormals();
 add(g,surface,new THREE.MeshStandardMaterial({vertexColors:true,roughness:.91}));
}
