function coconutGrain(){
 const size=128,pixels=new Uint8Array(size*size*4);
 for(let y=0;y<size;y++){
  for(let x=0;x<size;x++){
   const u=x/size*Math.PI*2,v=y/size*Math.PI*2;
   const clouds=Math.sin(5*u+Math.sin(3*v))*Math.cos(4*v-2*u);
   const hairs=Math.pow(.5+.5*Math.sin(39*u+.9*Math.sin(4*v)),7);
   const noise=Math.sin(112.91*x+23.27*y)*Math.cos(79.19*x-97.31*y);
   const grain=clouds*8+hairs*20+noise*15;
   pixels.set([113+grain,60+grain*.73,34+grain*.51,255],(y*size+x)*4);
  }
 }
 const texture=new THREE.DataTexture(pixels,size,size,THREE.RGBAFormat);
 texture.colorSpace=THREE.SRGBColorSpace;
 texture.wrapS=THREE.RepeatWrapping;
 texture.wrapT=THREE.RepeatWrapping;
 texture.magFilter=THREE.LinearFilter;
 texture.minFilter=THREE.LinearMipmapLinearFilter;
 texture.generateMipmaps=true;
 texture.needsUpdate=true;
 return texture;
}
