function football(g){
 const polyhedron=new THREE.IcosahedronGeometry(1,0);
 const vertices=polyhedron.getAttribute('position');
 const hexagons=[],neighbors=new Map();
 const key=v=>v.toArray().map(n=>n.toFixed(5)).join(',');
 const cut=(a,b)=>a.clone().lerp(b,1/3).normalize();
 const pentagons=[];
 for(let i=0;i<vertices.count;i+=3){
  const points=[0,1,2].map(j=>new THREE.Vector3().fromBufferAttribute(vertices,i+j));
  const hexagon=[];
  for(let j=0;j<3;j++){
   const a=points[j],b=points[(j+1)%3],p=cut(a,b),q=cut(b,a);
   hexagon.push(p,q);
   const hash=key(a);
   if(!neighbors.has(hash))neighbors.set(hash,{axis:a,points:new Map()});
   neighbors.get(hash).points.set(key(p),p);
   const reverse=key(b);
   if(!neighbors.has(reverse))neighbors.set(reverse,{axis:b,points:new Map()});
   neighbors.get(reverse).points.set(key(q),q);
  }
  hexagons.push(hexagon);
 }
 polyhedron.dispose();
 for(const {axis,points} of neighbors.values()){
  const ordered=[...points.values()];
  const u=ordered[0].clone().addScaledVector(axis,-ordered[0].dot(axis)).normalize();
  const v=axis.clone().cross(u);
  ordered.sort((a,b)=>Math.atan2(a.dot(v),a.dot(u))-Math.atan2(b.dot(v),b.dot(u)));
  pentagons.push(ordered);
 }
 add(g,new THREE.SphereGeometry(.486,36,24),footballSeam);
 for(const [panels,material] of [[hexagons,colors.white],[pentagons,footballPanel]]){
  const triangles=[];
  for(const panel of panels){
   const center=new THREE.Vector3().addVectors(panel[0],panel[1]);
   for(const v of panel.slice(2))center.add(v);
   center.normalize();
   const rim=panel.map(v=>v.clone().lerp(center,.029));
   for(let i=0;i<rim.length;i++){
    const a=rim[i],b=rim[(i+1)%rim.length];
    const project=(x,y)=>center.clone().multiplyScalar(1-x-y).addScaledVector(a,x).addScaledVector(b,y).normalize().multiplyScalar(.494+.008*(1-x-y)).toArray();
    const steps=4;
    for(let j=0;j<steps;j++)for(let k=0;k<steps-j;k++){
     const p=project(j/steps,k/steps),q=project((j+1)/steps,k/steps),r=project(j/steps,(k+1)/steps);
     triangles.push([p,q,r]);
     if(j+k<steps-1)triangles.push([q,project((j+1)/steps,(k+1)/steps),r]);
    }
   }
  }
  const mesh=faces(g,triangles,material);
  const position=mesh.geometry.getAttribute('position');
  const direction=new THREE.Vector3();
  const normal=mesh.geometry.getAttribute('normal');
  for(let i=0;i<position.count;i++){
   direction.fromBufferAttribute(position,i).normalize();
   normal.setXYZ(i,direction.x,direction.y,direction.z);
  }
 }
}

