function bowlingBall(g,color,vein){
 const material=plastic('#ffffff');
 material.vertexColors=true;
 material.roughness=.39;
 material.clearcoat=.10;
 const geometry=new THREE.SphereGeometry(.5,72,44);
 const surface=geometry.getAttribute('position');
 const holes=[[-.16,.15,.44],[.083,.161,.461],[-.062,-.127,.48]].map(p=>new THREE.Vector3(...p).normalize());
 const paint=new THREE.Color(color);
 const marble=vein?new THREE.Color(vein):null;
 const shade=new THREE.Color();
 const point=new THREE.Vector3();
 const shades=[];
 for(let i=0;i<surface.count;i++){
  point.fromBufferAttribute(surface,i);
  const angle=point.x*12+Math.sin(point.z*11+point.y*3)*1.7;
  const swirl=.9+.10*Math.sin(angle)+.07*Math.sin(2*angle+point.y*7);
  const depth=Math.max(...holes.map(dir=>{
   const distance=Math.sqrt(Math.max(0,.5-point.dot(dir)));
   return 1-THREE.MathUtils.smoothstep(distance,.050,.081);
  }));
  shade.copy(paint);
  if(marble){
   const wave=point.y*15+3*Math.sin(point.z*5-point.x*4)+1.8*Math.sin(point.x*7+point.z*4);
   const ribbon=THREE.MathUtils.smoothstep(.5+.5*Math.sin(wave),.38,.93);
   shade.lerp(marble,ribbon*.78);
  }
  shade.multiplyScalar((marble?1:swirl)*(1-.92*depth));
  shades.push(shade.r,shade.g,shade.b);
  point.multiplyScalar(1-depth*.092);
  surface.setXYZ(i,point.x,point.y,point.z);
 }
 geometry.setAttribute('color',new THREE.Float32BufferAttribute(shades,3));
 geometry.computeVertexNormals();
 add(g,geometry,material);
}

