function ballCurve(g,at,radius,material,count=96){
 const points=Array.from({length:count},(_,i)=>at(i/count*Math.PI*2));
 const path=new THREE.CatmullRomCurve3(points,true);
 return add(g,new THREE.TubeGeometry(path,count,radius,5,true),material);
}

function alternatingSeam(radius,phase){
 return angle=>{
  const latitude=.51*Math.cos(angle*2+phase);
  return new THREE.Vector3(Math.cos(angle)*Math.cos(latitude),Math.sin(latitude),
   Math.sin(angle)*Math.cos(latitude)).multiplyScalar(radius);
 };
}

function baseball(g){
 add(g,new THREE.SphereGeometry(.485,36,24),sportWhite);
 const at=alternatingSeam(.487,.35);
 ballCurve(g,at,.006,baseballThread);
 for(let i=0;i<52;i++){
  const angle=i/52*Math.PI*2;
  const p=at(angle),tangent=at(angle+.014).sub(at(angle-.014)).normalize();
  const across=p.clone().normalize().cross(tangent);
  const a=p.clone().addScaledVector(across,-.025).addScaledVector(tangent,-.009).setLength(.489);
  const b=p.clone().addScaledVector(across,.025).addScaledVector(tangent,.009).setLength(.489);
  rod(g,a.toArray(),b.toArray(),.006,baseballThread);
 }
 // Bake the reference winding into the geometry so each copy can roll freely.
 const q=new THREE.Quaternion().setFromEuler(new THREE.Euler(.18,.45,.08));
 for(const piece of g.children){
  piece.position.applyQuaternion(q);piece.quaternion.premultiply(q);
 }
}

