const poolFinishes=['#f6a006','#1730cb','#e63a11','#7a41b6','#ef7512','#1d8120','#85102d','#29282a'].map(color=>new THREE.MeshPhysicalMaterial({color,roughness:.44,metalness:0,clearcoat:.13,clearcoatRoughness:.35}));
