const poolNumberMaterials=new Map();
export const hasPoolBall=id=>id>=588&&id<=602;
export const solidItemSphereRadius=id=>hasPoolBall(id)? .491:0;
function poolNumberMaterial(number){
 if(poolNumberMaterials.has(number))return poolNumberMaterials.get(number);
 const material=new THREE.MeshStandardMaterial({color:'#faf8ed',roughness:.56});poolNumberMaterials.set(number,material);
 if(typeof document==='undefined')return material;
 const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;const ctx=canvas.getContext('2d');
 ctx.fillStyle='#faf8ed';ctx.fillRect(0,0,256,256);ctx.fillStyle='#1e2224';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`900 ${number<10?154:128}px "Arial Black",Arial,sans-serif`;printInk(ctx,String(number),128,136);
 if(number===6||number===9)ctx.fillRect(101,208,54,10);
 const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=4;material.color.set('#ffffff');material.map=texture;return material;
}
function numberedPoolBall(g,id){
 const number=id-587,finish=poolFinishes[(number-1)%8];
 add(g,new THREE.SphereGeometry(.49,48,32),number<=8?finish:poolIvory);
 if(number>8){
  const theta=Math.acos(.285/.4906);
  add(g,new THREE.SphereGeometry(.4906,48,18,0,Math.PI*2,theta,Math.PI-2*theta),finish);
 }
 const angle=.45,radius=.491,diameter=2*radius*Math.sin(angle);
 const badge=new THREE.SphereGeometry(radius,48,12,0,Math.PI*2,0,angle);badge.rotateX(Math.PI/2);
 const position=badge.attributes.position,uv=badge.attributes.uv;
 for(let i=0;i<position.count;i++)uv.setXY(i,.5+position.getX(i)/diameter,.5+position.getY(i)/diameter);
 add(g,badge,poolNumberMaterial(number));
 const reverse=badge.clone();reverse.rotateY(Math.PI);add(g,reverse,poolNumberMaterial(number));
}

const volleyballColors=[
 ['#29b7c7','#efa3c4','#26b3c5'],['#167447','#f8f3e8','#197c4d'],
 ['#e27525','#faf3e8','#e4822e'],['#d24081','#f68cb7','#d94884'],
 ['#eeeae9','#f7f4ef','#f0ecec'],['#2246b5','#f9f3e6','#f0ad19'],
];
function volleyball(g,palette){
 const seam=plastic('#bab5b5');
 const finishes=palette.map(plastic);
 add(g,new THREE.SphereGeometry(.487,30,22),seam);
 const axes=[
  [1,0,0],[1,Math.PI,0],[0,0,Math.PI/2],[0,0,-Math.PI/2],
  [1,Math.PI/2,0],[1,-Math.PI/2,0],
 ];
 for(const [axis,y,x] of axes){
  const matrix=new THREE.Matrix4().makeRotationFromEuler(new THREE.Euler(x,y,0));
  for(let stripe=0;stripe<3;stripe++){
   const start=-1+stripe*2/3+.019,end=start+2/3-.038;
   const vertices=[],normals=[],indices=[];
   for(let row=0;row<=6;row++)for(let col=0;col<=12;col++){
    const u=-.978+col/12*1.956;
    const offset=THREE.MathUtils.lerp(start,end,row/6);
    const v=offset+.09*(1-u*u)*(1-offset*offset);
    const point=new THREE.Vector3(axis?u:v,axis?v:-u,1).normalize().applyMatrix4(matrix);
    normals.push(point.x,point.y,point.z);
    point.multiplyScalar(.497);
    vertices.push(point.x,point.y,point.z);
   }
   for(let row=0;row<6;row++)for(let col=0;col<12;col++){
    const i=row*13+col;
    indices.push(i,i+1,i+13,i+1,i+14,i+13);
   }
   const geometry=new THREE.BufferGeometry();
   geometry.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));
   geometry.setAttribute('normal',new THREE.Float32BufferAttribute(normals,3));
   geometry.setAttribute('uv',new THREE.Float32BufferAttribute(new Float32Array(normals.length/3*2),2));
   geometry.setIndex(indices);
   add(g,geometry,finishes[stripe]);
  }
 }
}

