const pepperStem=new THREE.MeshStandardMaterial({color:'#51942b',roughness:.72});

function pepper(g,paint){
 const curve=new THREE.CatmullRomCurve3([
  new THREE.Vector3(-.155,-.51,.010),new THREE.Vector3(-.062,-.40,.027),
  new THREE.Vector3(.012,-.18,.033),new THREE.Vector3(.036,.065,.014),
  new THREE.Vector3(.026,.235,-.007),new THREE.Vector3(.015,.347,-.020),
 ]);
 const profile=new THREE.SplineCurve([
  [0,.005],[.16,.058],[.40,.128],[.68,.161],[.82,.163],[.92,.132],[1,.065],
 ].map(([x,y])=>new THREE.Vector2(x,y)));
 const vertices=[],indices=[],uv=[];
 const steps=28,sides=24;
 const radiusAt=profile.getPoints(steps);
 for(let row=0;row<=steps;row++){
  const t=row/steps,center=curve.getPoint(t),tangent=curve.getTangent(t);
  const across=new THREE.Vector3(tangent.y,-tangent.x,0).normalize();
  const forward=across.clone().cross(tangent);
  for(let i=0;i<sides;i++){
   const a=i/sides*Math.PI*2;
   const r=radiusAt[row].y*(1+.058*Math.sin(4*a+2*t)*t*t);
   const point=center.clone().addScaledVector(across,r*Math.cos(a)).addScaledVector(forward,r*.84*Math.sin(a));
   vertices.push(point.x,point.y,point.z);uv.push(i/sides,t);
   if(row<steps){
    const a=row*sides+i,b=row*sides+(i+1)%sides;
    indices.push(a,a+sides,b,b,a+sides,b+sides);
   }
  }
 }
 const skin=new THREE.BufferGeometry();
 skin.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));
 skin.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));
 skin.setIndex(indices);skin.computeVertexNormals();
 add(g,skin,paint);
 const shoulder=lathe(g,[[0,0],[.076,0],[.095,.016],[.063,.041],[.043,.064],[0,.074]],pepperStem);
 shoulder.position.set(.014,.329,-.019);
 rod(g,[.008,.379,-.019],[-.024,.48,-.029],.028,pepperStem);
 sphere(g,.029,.024,.029,pepperStem,-.025,.477,-.029);
}

