function cakeLayer(g,material,profile,phase,grain=false){
 const layer=lathe(g,profile,material);
 const p=layer.geometry.getAttribute('position');
 const tone=[];
 for(let i=0;i<p.count;i++){
  const x=p.getX(i),y=p.getY(i),z=p.getZ(i);
  const angle=Math.atan2(z,x),radius=Math.hypot(x,z);
  const lip=(.012*Math.cos(angle*11+phase)+.005*Math.sin(angle*17+phase))*Math.min(1,radius*3);
  p.setXYZ(i,x*(1+lip),y+lip*.95,z*(1+lip));
  if(grain){
   const shade=.94+.04*Math.cos(angle*18+y*37)+.025*Math.sin(y*120-angle*28);
   tone.push(shade,shade,shade);
  }
 }
 layer.geometry.computeVertexNormals();
 if(grain)layer.geometry.setAttribute('color',new THREE.Float32BufferAttribute(tone,3));
}

