function frostedIce(g){
 const geo=new RoundedBoxGeometry(.882,.897,.866,9,.112);
 const positions=geo.attributes.position;
 const base=new THREE.Color('#1770b2'),frost=new THREE.Color('#a9dcf2');
 const sample=new THREE.Color();
 const values=[];
 for(let i=0;i<positions.count;i++){
  const x=positions.getX(i),y=positions.getY(i),z=positions.getZ(i);
  const swirls=Math.sin(x*41+y*24+Math.sin(z*20)*3.8)*Math.sin(y*36-z*16);
  const vein=y-.9*x+.047*Math.sin(13*x-14*z)+.074;
  const branch=y-.39*x-.093+.026*Math.sin(24*x+15*z);
  const streak=Math.exp(-Math.pow(vein/.040,2))*.56;
  const haze=Math.exp(-Math.pow(vein/.13,2))*.19;
  const fork=Math.exp(-Math.pow(branch/.033,2))*.19;
  const edge=Math.max(0,Math.abs(x)+Math.abs(y)+Math.abs(z)-.85)*1.31;
  const weight=THREE.MathUtils.clamp(.064+swirls*.073+streak+haze+fork+edge+y*.21,0,1);
  values.push(...sample.copy(base).lerp(frost,weight).toArray());
 }
 geo.setAttribute('color',new THREE.Float32BufferAttribute(values,3));
 add(g,geo,iceFinish);
}

