const rainbowBands=['#24d6f3','#54dfa2','#f5e14e','#ffab35','#ed4d32','#d83542'];
const rainbowColors=rainbowBands.map(hex=>new THREE.Color(hex));
const iceGradient=new THREE.MeshStandardMaterial({vertexColors:true,roughness:.32});
function gradientOn(mesh,colors,minY,maxY){
 const positions=mesh.geometry.getAttribute('position');
 const color=new THREE.Color();
 const values=new Float32Array(positions.count*3);
 for(let i=0;i<positions.count;i++){
  const weight=THREE.MathUtils.clamp((positions.getY(i)-minY)/(maxY-minY),0,1)*(colors.length-1);
  const band=Math.min(colors.length-2,Math.floor(weight));
  color.copy(colors[band]).lerp(colors[band+1],weight-band).toArray(values,i*3);
 }
 mesh.geometry.setAttribute('color',new THREE.BufferAttribute(values,3));
}
function rainbowPop(g){
 const outline=new THREE.Shape();
 outline.moveTo(-.278,-.240);outline.lineTo(.278,-.240);outline.lineTo(.278,.159);
 outline.absarc(0,.159,.278,0,Math.PI,false);
 outline.closePath();
 const edge=new THREE.ExtrudeGeometry(outline,{depth:.17,bevelSize:.043,bevelThickness:.037,bevelSegments:4,curveSegments:18});
 edge.translate(0,0,-.085);
 const body=add(g,edge,iceGradient,0,.119);
 // Set the gradient in the shader's vertex data for the curved edge.
 // Flat faces carry matching gradient colors on subdivided quads.
 const clipped=new THREE.BufferGeometry();
 const vertices=[];
 const right=y=>y<=.159?.278:Math.sqrt(Math.max(0,.278**2-(y-.159)**2));
 for(const side of [-1,1]){
  for(let i=0;i<26;i++){
   const a=-.240+i*.677/26,b=-.240+(i+1)*.677/26;
   const l=right(a),r=right(b),z=side*.123;
   const row=[[-l,a,z],[l,a,z],[r,b,z],[-l,a,z],[r,b,z],[-r,b,z]];
   if(side<0)row.reverse();
   vertices.push(...row.flat());
  }
 }
 clipped.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));
 clipped.setAttribute('uv',new THREE.Float32BufferAttribute(new Float32Array(vertices.length/3*2),2));
 clipped.computeVertexNormals();
 const face=add(g,clipped,iceGradient,0,.119,0);
 gradientOn(body,rainbowColors,-.268,.437);
 gradientOn(face,rainbowColors,-.268,.437);
 box(g,.166,.33,.089,colors.wood,0,-.347,0,.081);
}
