function packagingInk(base,draw){
 const ink=plastic(base);
 if(typeof document==='undefined')return ink;
 const surface=document.createElement('canvas');
 surface.width=192;surface.height=256;
 const ctx=surface.getContext('2d');
 ctx.fillStyle=base;ctx.fillRect(0,0,192,256);
 draw(ctx);
 const texture=new THREE.CanvasTexture(surface);
 texture.colorSpace=THREE.SRGBColorSpace;
 ink.color.set(0xffffff);
 ink.map=texture;
 ink.roughness=.69;
 return ink;
}
