function mugPattern(ctx,paint,pattern){
 ctx.fillStyle=paint;
 if(pattern==='stripe'||pattern==='wave'){
  for(let x=0;x<192;x+=48){
   ctx.beginPath();
   ctx.moveTo(x,0);
   if(pattern==='wave'){
    ctx.bezierCurveTo(x+28,80,x-18,177,x+4,256);
    ctx.lineTo(x+26,256);
    ctx.bezierCurveTo(x+4,174,x+50,76,x+22,0);
    ctx.fill();
   }else ctx.fillRect(x,0,19,256);
  }
  return;
 }
 for(let i=0;i<18;i++){
  const row=Math.floor(i/6);
  const x=(12+(i%6)*32+(row%2)*14)%192,y=44+row*82;
  ctx.save();
  ctx.translate(x,y);
  ctx.scale(.74,1.5);
  if(pattern==='cloud'){
   circleInk(ctx,0,-7,9,paint);circleInk(ctx,6,2,8,paint);circleInk(ctx,-6,3,7,paint);
  }else if(pattern==='flower'){
   for(let j=0;j<5;j++){
    const a=j*Math.PI*2/5;
    circleInk(ctx,8*Math.cos(a),10*Math.sin(a),5,paint);
   }
   circleInk(ctx,0,0,4,'#e4a858');
  }else if(pattern==='diamond'){
   ctx.fillStyle=paint;
   ctx.beginPath();ctx.moveTo(0,-15);ctx.lineTo(9,0);ctx.lineTo(0,15);ctx.lineTo(-9,0);ctx.fill();
  }else if(pattern==='heart'){
   ctx.fillStyle=paint;
   ctx.beginPath();ctx.moveTo(0,16);
   ctx.bezierCurveTo(-20,-6,-9,-18,0,-8);
   ctx.bezierCurveTo(9,-18,20,-6,0,16);ctx.fill();
  }else circleInk(ctx,0,0,5,paint);
  ctx.restore();
 }
}
