const clockPaints=['#357cbf','#65a940','#db842f','#d879a8','#8c4cb1','#b52a2e','#ded9d3','#deb72b'].map(plastic);
const clockTimber=new THREE.MeshStandardMaterial({color:'#81543a',roughness:.67});
const clockEdge=new THREE.MeshStandardMaterial({color:'#8c5636',roughness:.58});
const clockRecess=new THREE.MeshStandardMaterial({color:'#31353e',roughness:.76});
const clockBrass=new THREE.MeshStandardMaterial({color:'#d5a52d',metalness:.32,roughness:.4});
let clockFaceMaterial;
function mantelDial(){
 if(clockFaceMaterial)return clockFaceMaterial;
 clockFaceMaterial=new THREE.MeshStandardMaterial({color:'#d9d5dc',roughness:.85});
 if(typeof document==='undefined')return clockFaceMaterial;
 const canvas=document.createElement('canvas');canvas.width=canvas.height=256;
 const ctx=canvas.getContext('2d');
 ctx.fillStyle='#d9d5dc';ctx.fillRect(0,0,256,256);
 ctx.fillStyle='#343d6b';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='bold 27px Georgia';
 for(let hour=1;hour<=12;hour++){
  const angle=hour*Math.PI/6;
  printInk(ctx,String(hour),128+91*Math.sin(angle),130-91*Math.cos(angle));
 }
 ctx.strokeStyle='#5f637c';ctx.lineWidth=2;
 for(let tick=0;tick<60;tick++){
  if(tick%5===0)continue;
  const angle=tick*Math.PI/30;
  ctx.beginPath();ctx.moveTo(128+113*Math.sin(angle),128-113*Math.cos(angle));
  ctx.lineTo(128+119*Math.sin(angle),128-119*Math.cos(angle));ctx.stroke();
 }
 const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;
 clockFaceMaterial.color.set(0xffffff);clockFaceMaterial.map=texture;
 return clockFaceMaterial;
}
function clockProfile(width,bottom,shoulder,crown){
 const shape=new THREE.Shape();
 shape.moveTo(-width/2,bottom);shape.lineTo(-width/2,shoulder);
 shape.bezierCurveTo(-width*.36,shoulder+.015,-width*.18,crown,0,crown);
 shape.bezierCurveTo(width*.18,crown,width*.36,shoulder+.015,width/2,shoulder);
 shape.lineTo(width/2,bottom);shape.closePath();
 return shape;
}
function clockExtrusion(g,shape,depth,material,z,bevel=.012,high=true){
 const geo=new THREE.ExtrudeGeometry(shape,{depth,bevelEnabled:true,bevelSize:bevel,bevelThickness:bevel,bevelSegments:high?4:2,curveSegments:high?24:8});
 geo.translate(0,0,z);
 return add(g,geo,material);
}
function mantelClock(g,paint,{high=true,dial=mantelDial(),timber=clockTimber,edge=clockEdge,hands=clockBrass}={}){
 const rounded=(w,h,d,m,x,y,z,r)=>box(g,w,h,d,m,x,y,z,r,high);
 clockExtrusion(g,clockProfile(.436,-.377,.34,.423),.247,paint,-.129,.017,high);
 // The dark inset is recessed between the two painted pillars.
 clockExtrusion(g,clockProfile(.288,-.326,.294,.349),.012,clockRecess,.13,.007,high);
 add(g,new THREE.PlaneGeometry(.205,.31),paint,0,-.13,.151);
 for(const side of [-1,1]){
  rounded(.044,.649,.045,clockRecess,side*.184,-.013,.137,.018);
  rounded(.012,.617,.014,timber,side*.216,-.013,.154,.005);
 }
 const cap=new THREE.Shape();
 cap.moveTo(-.281,.336);
 cap.bezierCurveTo(-.174,.35,-.109,.454,0,.454);
 cap.bezierCurveTo(.109,.454,.174,.35,.281,.336);
 cap.lineTo(.281,.388);
 cap.bezierCurveTo(.153,.41,.097,.507,0,.507);
 cap.bezierCurveTo(-.097,.507,-.153,.41,-.281,.388);
 cap.closePath();
 clockExtrusion(g,cap,.304,paint,-.15,.014,high);
 const fascia=new THREE.Shape();
 fascia.moveTo(-.279,.338);
 fascia.bezierCurveTo(-.174,.352,-.109,.455,0,.455);
 fascia.bezierCurveTo(.109,.455,.174,.352,.279,.338);
 fascia.lineTo(.279,.365);
 fascia.bezierCurveTo(.159,.387,.099,.479,0,.479);
 fascia.bezierCurveTo(-.099,.479,-.159,.387,-.279,.365);
 fascia.closePath();
 clockExtrusion(g,fascia,.009,timber,.169,.005,high);
 rounded(.488,.079,.308,timber,0,-.392,0,.023);
 rounded(.522,.041,.325,edge,0,-.354,0,.02);
 for(const side of [-1,1])rounded(.105,.065,.242,timber,side*.158,-.454,0,.023);
 rounded(.363,.023,.272,timber,0,-.438,0,.011);
 // Solid bezel, hands, and pendulum retain depth even at oblique pile angles.
 disc(g,.155,.017,edge,0,.197,.157);
 add(g,new THREE.CircleGeometry(.144,high?64:32),dial,0,.197,.169);
 torus(g,.146,.006,clockBrass,0,.197,.174,high?28:20);
 rod(g,[0,.047,.157],[0,-.18,.157],.009,clockBrass);
 disc(g,.075,.024,clockBrass,0,-.167,.173);
 torus(g,.064,.006,edge,0,-.167,.188,high?28:16);
 rod(g,[0,.197,.183],[0,.303,.183],.007,hands);
 rod(g,[0,.197,.188],[-.066,.145,.188],.009,hands);
 disc(g,.014,.013,clockBrass,0,.197,.192);
 // The photographed reverse has horizontal painted slats between dark rails.
 add(g,new THREE.BoxGeometry(.31,.585,.016),clockRecess,0,-.026,-.144);
 for(let row=0;row<23;row++)add(g,new THREE.BoxGeometry(.303,.018,.011),paint,0,-.296+row*.0245,-.159);
 for(const side of [-1,1])rounded(.035,.622,.022,clockRecess,side*.177,-.026,-.158,.008);
 clockExtrusion(g,fascia,.009,timber,-.187,.005,high);
}

