const steamedDough=new THREE.MeshStandardMaterial({color:'#faf0d7',roughness:.87});
const toastedDough=new THREE.MeshStandardMaterial({color:'#bb6b26',roughness:.8});
const sesame=new THREE.MeshStandardMaterial({color:'#e9c998',roughness:.88});
const friedDough=new THREE.MeshStandardMaterial({color:'#ca7831',roughness:.74});
const sweetRice=new THREE.MeshStandardMaterial({color:'#698a39',roughness:.62});
const riceFlour=new THREE.MeshStandardMaterial({color:'#a0ac58',roughness:.79});

function steamedBun(g){
 const profile=[[0,-.23],[.15,-.23],[.29,-.208],[.397,-.137],[.432,-.022],
  [.418,.087],[.346,.201],[.244,.296],[.127,.347],[.041,.354],[0,.315]];
 const geometry=new THREE.LatheGeometry(profile.map(([r,y])=>new THREE.Vector2(r,y)),88);
 const vertices=geometry.attributes.position;
 for(let i=0;i<vertices.count;i++){
  const x=vertices.getX(i),y=vertices.getY(i),z=vertices.getZ(i);
  const angle=Math.atan2(z,x);
  const bite=Math.max(0,Math.sin(angle*11+y*10))**4;
  const crown=THREE.MathUtils.smoothstep(y,-.05,.27);
  const indent=1-.26*bite*crown;
  vertices.setXYZ(i,x*indent,y-.03*bite*crown,z*indent);
 }
 geometry.computeVertexNormals();
 add(g,geometry,steamedDough).rotation.x=1.13;
}
function sesameFlatbread(g){
 lathe(g,[[0,-.144],[.326,-.14],[.426,-.091],[.465,-.015],
  [.46,.076],[.408,.13],[.315,.155],[.125,.162],[0,.163]],toastedDough).rotation.x=1;
 for(let i=0;i<38;i++){
  const angle=i*2.399963;
  const radius=.37*Math.sqrt((i+.2)/38);
  const y=.162-.021*(radius/.37)**2;
  const x=radius*Math.cos(angle),z=radius*Math.sin(angle);
  const seed=sphere(g,.021,.006,.009,sesame,x,y*Math.cos(1)-z*Math.sin(1),y*Math.sin(1)+z*Math.cos(1));
  seed.rotation.set(1,angle,angle);
 }
}
function friedDoughStick(g){
 for(const side of [-1,1]){
  const skin=lathe(g,[[0,-.457],[.079,-.458],[.129,-.41],[.139,-.287],[.148,-.155],
   [.131,.018],[.145,.19],[.13,.356],[.102,.444],[.052,.466],[0,.459]],friedDough);
  skin.position.set(side*.104,0,0);
  skin.rotation.z=side*.07;
  const p=skin.geometry.attributes.position;
  for(let i=0;i<p.count;i++){
   const x=p.getX(i),y=p.getY(i),z=p.getZ(i);
   const wrinkle=1+.098*Math.sin(y*31+3*Math.atan2(z,x))+.057*Math.cos(y*57-Math.atan2(z,x)*7);
   p.setXYZ(i,x*wrinkle,y,z*wrinkle);
  }
  skin.geometry.computeVertexNormals();
 }
}
function steamedMantou(g){
 const dough=new THREE.Group();
 lathe(dough,[[0,-.36],[.27,-.36],[.316,-.352],[.338,-.322],
  [.349,-.18],[.355,.08],[.347,.27],[.33,.333],[.301,.352],[0,.352]],steamedDough);
 // The cut face carries a shallow rolled seam, unlike a pinched bun crown.
 const points=[];
 for(let i=0;i<=96;i++){
  const a=i/96*Math.PI*3.5,r=.018+.245*i/96;
  points.push(new THREE.Vector3(r*Math.cos(a),.354,r*Math.sin(a)));
 }
 const seam=new THREE.MeshStandardMaterial({color:'#e3d7bb',roughness:.94});
 add(dough,new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),96,.0035,5,false),seam);
 dough.rotation.set(.96,-.15,-.13);dough.updateMatrix();
 for(const child of [...dough.children]){
  child.updateMatrix();child.matrix.premultiply(dough.matrix);
  child.matrix.decompose(child.position,child.quaternion,child.scale);g.add(child);
 }
}

