let householdMatchboxMaterial;
function householdMatchbox(g){
 if(!householdMatchboxMaterial){
  const material=new THREE.MeshStandardMaterial({color:'#eee0b3',roughness:.93});
  householdMatchboxMaterial=material;
  if(typeof document!=='undefined'){
   const canvas=document.createElement('canvas');canvas.width=256;canvas.height=288;
   const ctx=canvas.getContext('2d');ctx.fillStyle='#f2e1ab';ctx.fillRect(0,0,256,288);
   ctx.strokeStyle='#ab332a';ctx.lineWidth=8;ctx.strokeRect(10,10,236,268);
   ctx.fillStyle='#ab332a';ctx.font='bold 70px "PingFang SC","Heiti SC",sans-serif';ctx.textAlign='center';printInk(ctx,'火柴',128,92);
   ctx.font='28px "PingFang SC","Heiti SC",sans-serif';printInk(ctx,'日用安全火柴',128,253);
   ctx.save();ctx.translate(128,172);ctx.fillStyle='#b83928';
   for(let i=0;i<5;i++){ctx.rotate(Math.PI*2/5);ctx.beginPath();ctx.ellipse(0,-32,16,27,0,0,Math.PI*2);ctx.fill();}
   ctx.fillStyle='#db9e39';ctx.beginPath();ctx.arc(0,0,15,0,Math.PI*2);ctx.fill();ctx.restore();
   const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;
   material.color.set('#ffffff');material.map=texture;
  }
 }
 campingMatchbox(g,1441,householdMatchboxMaterial);
}
