function mirrorBall(g,finish,glint){
 const mirror=new THREE.IcosahedronGeometry(.398,3);
 add(g,mirror,finish);
 const shine=new THREE.IcosahedronGeometry(.406,3);
 const positions=shine.attributes.position;
 const facets=[];
 for(let i=0;i<positions.count;i+=3){
  if((i*13)%17>=4)continue;
  for(let j=i;j<i+3;j++)facets.push(positions.getX(j),positions.getY(j),positions.getZ(j));
 }
 const mosaic=new THREE.BufferGeometry();
 mosaic.setAttribute('position',new THREE.Float32BufferAttribute(facets,3));
 mosaic.setAttribute('uv',new THREE.Float32BufferAttribute(new Float32Array(facets.length/3*2),2));
 mosaic.computeVertexNormals();
 add(g,mosaic,glint);
 torus(g,.062,.015,breakfastSteel,0,.403,0,20);
 g.rotation.set(.21,-.19,.10);
}

