function heartBalloon(g){
 picnicBalloon(g,[paradeRed],true);
 const heart=new THREE.Shape();
 heart.moveTo(0,-.141);
 heart.bezierCurveTo(-.236,.007,-.172,.187,-.050,.151);
 heart.quadraticCurveTo(-.016,.143,0,.111);
 heart.quadraticCurveTo(.016,.143,.050,.151);
 heart.bezierCurveTo(.172,.187,.236,.007,0,-.141);
 const icon=new THREE.ExtrudeGeometry(heart,{depth:.008,bevelEnabled:true,bevelSegments:1,bevelSize:.007,bevelThickness:.005,curveSegments:10});
 for(const side of [-1,1]){
  const badge=add(g,icon.clone(),toyPink,0,.150,.286*side);
  badge.rotation.y=side<0?Math.PI:0;
  const points=badge.geometry.attributes.position;
  for(let i=0;i<points.count;i++){
   const x=points.getX(i),y=points.getY(i);
   const surface=.293*Math.sqrt(1-(x/.365)**2-((y+.022)/.373)**2);
   points.setZ(i,points.getZ(i)+surface-.280);
  }
  badge.geometry.computeVertexNormals();
 }
 icon.dispose();
 g.rotation.set(.18,-.21,.10);
}

