function starBalloon(g){
 picnicBalloon(g,[maracaYellow],true);
 const points=Array.from({length:10},(_,index)=>{
  const angle=Math.PI/2+index*Math.PI/5;
  const radius=index%2?.047:.102;
  return [radius*Math.cos(angle),radius*Math.sin(angle)];
 });
 for(const side of [-1,1]){
  for(const [x,y] of [[-.118,.099],[.095,.221]]){
   const z=.293*Math.sqrt(1-(x/.365)**2-((y-.128)/.373)**2);
   const badge=polygon(g,points,.012,ceramicIvory);
   badge.position.set(x,y,z*side);
   badge.rotation.set(-side*(y-.128)*2.4,side*x*2.7,0);
  }
 }
 g.rotation.set(.23,-.15,.05);
}

function roundedSportLetter(g,letter,finish){
 const line=new THREE.Path();
 if(letter==='S'){
  line.moveTo(.210,.266);
  line.bezierCurveTo(.105,.472,-.283,.405,-.244,.167);
  line.bezierCurveTo(-.225,.019,.246,.073,.238,-.172);
  line.bezierCurveTo(.229,-.422,-.162,-.404,-.247,-.277);
 }else if(letter==='O'){
  line.absellipse(0,0,.255,.337,0,Math.PI*2);
 }else{
  line.moveTo(-.218,-.336);
  line.lineTo(-.218,.321);
  line.lineTo(.043,.321);
  line.bezierCurveTo(.307,.324,.296,-.015,.036,-.014);
  line.lineTo(-.218,-.014);
 }
 const points=line.getPoints(22).map(({x,y})=>new THREE.Vector3(x,y,0));
 const closed=letter==='O';
 if(closed)points.pop();
 add(g,new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points,closed),66,.092,10,closed),finish);
 if(!closed)for(const point of [points[0],points.at(-1)])sphere(g,.092,.092,.092,finish,point.x,point.y,0);
 if(letter==='R'){
  rod(g,[-.019,-.004,0],[.232,-.325,0],.092,finish);
  sphere(g,.092,.092,.092,finish,.232,-.325,0);
 }
 g.rotation.set(.17,-.21,.08);
}

