function numberPlayTile(g,number,finish){
 letterTile(g,(tile,ink)=>{
  const line=new THREE.Path();
  if(number===1){
   line.moveTo(-.106,.107);line.lineTo(.017,.176);line.lineTo(.017,-.175);
   rod(tile,[-.098,-.179,.169],[.127,-.179,.169],.029,ink);
  }else{
   line.moveTo(-.132,.112);
   line.bezierCurveTo(-.097,.225,.163,.220,.145,.103);
   line.quadraticCurveTo(.139,.048,-.004,-.024);
   line.quadraticCurveTo(-.100,-.072,-.133,-.179);
   line.lineTo(.145,-.179);
  }
  const points=line.getPoints(14).map(({x,y})=>new THREE.Vector3(x,y,.169));
  add(tile,new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),40,.029,8,false),ink);
  for(const point of [points[0],points.at(-1)])sphere(tile,.029,.029,.029,ink,point.x,point.y,point.z);
 },finish);
}

