const abacusFrame=plastic('#945838');
const abacusBead=plastic('#a84331');
const abacusBeam=plastic('#d19f70');
function framedAbacus(g){
 for(const x of [-.421,.421])box(g,.10,.75,.151,abacusFrame,x,0,0,.030);
 for(const y of [-.328,.328])box(g,.868,.096,.164,abacusFrame,0,y,0,.028);
 box(g,.856,.052,.137,abacusBeam,0,.113,0,.018);
 for(let column=0;column<7;column++){
  const x=(column-3)*.108;
  rod(g,[x,-.303,0],[x,.303,0],.012,abacusEnd);
  const lowerOffset=column===2||column===4?.032:0;
  for(const y of [.221,.281,.030+lowerOffset,-.035+lowerOffset,-.100,-.165,-.230]){
   lathe(g,[[0,-.027],[.025,-.027],[.045,-.009],[.045,.009],[.025,.027],[0,.027]],abacusBead).position.set(x,y,0);
  }
  if(column===3||column===6)disc(g,.011,.007,colors.cream,x,.113,.070);
 }
 g.rotation.set(.20,-.17,-.09);
}

