function digitPlayTile(g,number,finish){
 letterTile(g,(tile,ink)=>{
  for(const index of digitStrokes[number]){
   const [from,to]=digitSegments[index].map(([x,y])=>[x,y,.165]);
   rod(tile,from,to,.027,ink);
   for(const [x,y,z] of [from,to])sphere(tile,.027,.027,.027,ink,x,y,z);
  }
 },finish);
}
