const animalCream=plastic('#f5e6c9');

function toyEyes(g,x,y,z,spread){
 for(const side of [-1,1]){
  const eyeX=x+side*spread;
  sphere(g,.026,.034,.015,animalEye,eyeX,y,z);
  sphere(g,.008,.009,.006,colors.white,eyeX-.007,y+.010,z+.012);
 }
}

function moldedCurve(g,points,radius,finish,segments=28){
 const curve=new THREE.CatmullRomCurve3(points.map(point=>new THREE.Vector3(...point)));
 add(g,new THREE.TubeGeometry(curve,segments,radius,10,false),finish);
}

