function toySpaceShuttle(g,body,trim){
 const profile=[[0,-.369],[.145,-.370],[.195,-.290],[.208,-.156],[.179,.083],
  [.145,.213],[.096,.337],[.045,.440],[0,.470]];
 lathe(g,profile,body);
 const wing=[ [.144,.057],[.231,-.096],[.377,-.303],[.347,-.376],[.135,-.343] ];
 for(const side of [-1,1]){
  polygon(g,wing.map(([x,y])=>[side*x,y]),.084,trim,-.043);
  const jet=lathe(g,[[0,-.425],[.085,-.423],[.087,-.385],[.071,-.329],[0,-.322]],cargoGray);
  jet.position.x=side*.112;
  box(g,.121,.032,.024,body,side*.253,-.294,.058,.011).rotation.z=side*.18;
 }
 sphere(g,.105,.127,.060,vehicleGlass,0,.206,.129);
 sphere(g,.059,.034,.019,chairBlue,-.018,.230,.180).rotation.z=.25;
 lathe(g,[[.174,-.290],[.200,-.273],[.205,-.243]],ceramicIvory);
 g.rotation.set(.21,-.28,-.12);
}

function toySatellite(g,body,solar){
 box(g,.326,.313,.270,body,0,-.035,0,.074);
 box(g,.256,.236,.051,ceramicIvory,0,-.034,.129,.052);
 for(const side of [-1,1]){
  rod(g,[side*.108,-.031,0],[side*.365,-.031,0],.044,cargoGray);
  box(g,.237,.355,.055,cargoGray,side*.338,-.030,0,.027);
  box(g,.208,.318,.013,solar,side*.338,-.030,.032,.013);
  for(const y of [-.126,-.062,.003,.067]){
   box(g,.196,.010,.014,chairBlue,side*.338,y,.044,.003);
  }
  box(g,.012,.310,.015,chairBlue,side*.338,-.030,.044,.005);
 }
 const dish=lathe(g,[[0,.112],[.059,.115],[.113,.132],[.163,.173],[.174,.199],
  [.161,.200],[.116,.166],[.056,.147],[0,.145]],ceramicIvory);
 dish.rotation.set(.22,0,-.27);
 dish.position.set(.041,.091,.008);
 rod(g,[.081,.241,.055],[.111,.322,.098],.022,body);
 sphere(g,.043,.041,.043,body,.111,.322,.098);
 disc(g,.042,.032,fleetBlue,0,-.026,.163);
 g.rotation.set(.27,-.26,.13);
}

