function curvedToyJ(g,finish){
 const stroke=new THREE.Path();
 stroke.moveTo(.190,.327);
 stroke.lineTo(.190,-.128);
 stroke.quadraticCurveTo(.190,-.340,-.032,-.340);
 stroke.quadraticCurveTo(-.207,-.340,-.247,-.185);
 const points=stroke.getPoints(15).map(({x,y})=>[x,y,0]);
 moldedCurve(g,points,.083,finish,44);
 for(const point of [points[0],points.at(-1)])sphere(g,.083,.083,.083,finish,...point);
 rod(g,[-.020,.327,0],[.255,.327,0],.081,finish);
 g.rotation.set(.15,-.19,.05);
}

