function marketPorcelainAnimal(g,body,cat){
 const scarf=cat?paradeRed:fleetBlue;
 sphere(g,.231,.259,.188,body,0,-.166,0);
 sphere(g,.226,.200,.178,body,0,.162,.045);
 sphere(g,.135,.142,.027,porcelainCream,0,-.155,.172);
 for(const side of [-1,1]){
  sphere(g,.104,.078,.092,body,side*.122,-.356,.085);
  if(cat){
   const ear=[[side*.075,.264],[side*.230,.259],[side*.201,.447]];
   polygon(g,ear,.105,body,.002);
   polygon(g,[[side*.125,.280],[side*.198,.280],[side*.182,.393]],.009,softPink,.117);
  }else{
   sphere(g,.088,.176,.079,body,side*.207,.142,.023).rotation.z=side*.270;
   sphere(g,.048,.122,.029,porcelainCream,side*.223,.129,.085).rotation.z=side*.270;
  }
 }
 toyEyes(g,0,.178,.213,.081);
 sphere(g,.094,.047,.023,porcelainCream,0,.079,.213);
 sphere(g,.041,.026,.017,lacquerInk,0,.115,.234);
 torus(g,.181,.029,scarf,0,-.022,0,40).rotation.x=Math.PI*.5;
 sphere(g,.043,.040,.024,porcelainGold,0,-.073,.196);
 if(cat){
  for(const side of [-1,1]){
   rod(g,[side*.078,.100,.218],[side*.173,.124,.194],.010,porcelainGold);
   rod(g,[side*.078,.072,.216],[side*.174,.060,.189],.009,porcelainGold);
  }
  for(const x of [-.038,0,.038])box(g,.015,.040,.008,porcelainGold,x,.276,.190,.005,false);
  moldedCurve(g,[[.126,-.155,.066],[.245,-.061,.137],[.275,.048,.174],[.261,.160,.184]],.074,body);
  sphere(g,.075,.081,.058,body,.262,.170,.185);
  for(const offset of [-.021,.021])box(g,.009,.039,.008,porcelainCream,.261+offset,.182,.237,.004,false);
 }else{
  sphere(g,.073,.136,.105,body,-.220,-.233,.094);
  sphere(g,.073,.136,.105,body,.220,-.233,.094);
 }
 g.rotation.set(.18,-.21,-.03);
}

