function fairGate(g,finish){
 box(g,.855,.129,.404,mochaBrown,0,-.337,0,.035);
 for(const x of [-.333,.333]){
  box(g,.133,.464,.300,finish,x,-.082,0,.028);
  box(g,.101,.120,.015,porcelainGold,x,-.073,.149,.023);
 }
 box(g,.674,.143,.313,finish,0,.140,0,.033);
 for(const side of [-1,1]){
  const roof=polygon(g,[[0,.371],[side*.442,.240],[side*.466,.163],[0,.215]],.341,finish,-.173);
  roof.rotation.y=side*.04;
  moldedCurve(g,[[0,.375,.179],[side*.201,.298,.200],[side*.388,.229,.197],[side*.460,.250,.203]],.019,porcelainGold,22);
 }
 box(g,.245,.100,.025,porcelainCream,0,.168,.167,.021);
 box(g,.148,.014,.009,mochaBrown,0,.170,.187,.005,false);
 g.rotation.set(.23,-.19,-.03);
}

function fairOperaCrown(g,finish,colorful){
 const crown=lathe(g,[[0,-.247],[.288,-.247],[.332,-.217],[.351,-.120],[.319,.104],[.248,.252],[.158,.316],[.059,.328],[0,.328]],finish);
 crown.scale.z=.74;
 for(const side of [-1,1]){
  moldedCurve(g,[[side*.110,.077,.047],[side*.237,.287,.057],[side*.326,.400,.101]],.039,porcelainGold,18);
  sphere(g,.059,.058,.049,colorful?(side<0?toyPink:gardenGreen):paradeRed,side*.331,.411,.111);
  rod(g,[side*.255,-.147,.153],[side*.288,-.349,.194],.019,porcelainGold);
  sphere(g,.036,.063,.031,paradeRed,side*.294,-.345,.194);
 }
 sphere(g,.067,.063,.023,porcelainGold,0,.144,.234);
 sphere(g,.037,.036,.013,porcelainCream,0,.148,.257);
 for(const [i,x] of [-.228,-.116,0,.116,.228].entries()){
  const jewel=colorful?[toyPink,paradeGold,toyLavender,gardenGreen,musicOrange][i]:porcelainGold;
  sphere(g,.030,.031,.025,jewel,x,-.119,.236-.72*x*x);
 }
 g.rotation.set(.18,-.22,-.04);
}

function fairTigerHat(g,finish){
 const hat=lathe(g,[[0,-.236],[.242,-.234],[.328,-.207],[.379,-.072],[.354,.084],[.295,.206],[.182,.304],[.065,.323],[0,.323]],finish);
 hat.scale.z=.80;
 for(const side of [-1,1]){
  sphere(g,.112,.112,.065,finish,side*.229,.209,.009);
  sphere(g,.065,.066,.021,softPink,side*.238,.216,.064);
  sphere(g,.070,.049,.025,porcelainCream,side*.128,.044,.253);
  sphere(g,.035,.050,.016,lacquerInk,side*.128,.067,.276);
  sphere(g,.012,.017,.006,porcelainCream,side*.139,.081,.289);
  const stripes=[[-.052,.076],[-.102,.064],[-.151,.053]];
  for(const [y,width] of stripes){
   rod(g,[side*.221,y,.233],[side*(.221+width),y+.019,.194],.011,lacquerInk);
  }
 }
 sphere(g,.107,.055,.021,porcelainCream,0,-.085,.293);
 sphere(g,.041,.025,.021,lacquerInk,0,-.046,.315);
 for(const [y,w] of [[.219,.106],[.174,.064],[.130,.106]])box(g,w,.017,.010,lacquerInk,0,y,.246+( .219-y)*.38,.006,false);
 rod(g,[0,.124,.277],[0,.216,.254],.010,lacquerInk);
 g.rotation.set(.15,-.20,-.03);
}

function fairCloudShield(g,finish){
 const contour=[[-.367,.310],[-.316,.373],[.316,.373],[.367,.310],[.341,-.100],[.229,-.264],[0,-.415],[-.229,-.264],[-.341,-.100]];
 polygon(g,contour,.096,porcelainGold,-.060);
 polygon(g,contour.map(([x,y])=>[x*.88,y*.88]),.063,finish,.012);
 const curl=new THREE.ShapePath();
 curl.moveTo(-.216,-.079);
 curl.bezierCurveTo(-.314,.070,-.078,.163,-.040,.047);
 curl.bezierCurveTo(-.021,-.005,-.085,-.057,-.125,-.010);
 curl.moveTo(-.038,.046);
 curl.bezierCurveTo(.061,.204,.255,.096,.194,.018);
 curl.bezierCurveTo(.175,-.018,.110,-.006,.124,.039);
 curl.moveTo(-.222,-.107);
 curl.quadraticCurveTo(.037,-.171,.227,-.099);
 for(const shape of curl.subPaths){
  moldedCurve(g,shape.getPoints(17).map(({x,y})=>[x,y,.083]),.014,porcelainCream,25);
 }
 g.rotation.set(.26,-.21,-.14);
}

