 const inner=lathe(g,[[.050,-.369],[.224,-.369],[.220,-.343],[.159,-.314],[.110,-.267],[.068,-.202]],lacquerInk);
 inner.rotation.y=Math.PI;
 torus(g,.246,.022,porcelainGold,0,-.368,0,38).rotation.x=Math.PI*.5;
 rod(g,[0,-.113,0],[0,.337,0],.057,toastCrust);
 for(const y of [-.042,.033,.107,.181,.252])sphere(g,.015,.013,.012,lacquerInk,0,y,.054);
