const cinemaCharcoal=plastic('#333347');
const cinemaIceLens=plastic('#4799c4');
const cinemaRoseLens=plastic('#c95075');

function cinemaReel(g,finish,x=0,y=0,z=0,r=.380){
 const ring=new THREE.Shape();
 ring.absarc(0,0,r,0,Math.PI*2,false);
 for(let i=0;i<5;i++){
  const angle=i*Math.PI*2/5+.30;
  const opening=new THREE.Path();
  opening.absarc(Math.cos(angle)*r*.607,Math.sin(angle)*r*.607,r*.155,0,Math.PI*2,true);
  ring.holes.push(opening);
 }
 const hub=new THREE.Path();
 hub.absarc(0,0,r*.124,0,Math.PI*2,true);
 ring.holes.push(hub);
 for(const offset of [-.043,.035]){
  const flange=add(g,new THREE.ExtrudeGeometry(ring,{depth:.018,bevelEnabled:true,bevelThickness:.006,bevelSize:.006,bevelSegments:2,curveSegments:14}),finish,x,y,z+offset);
  flange.castShadow=true;
  torus(g,r*.94,.008,finish,x,y,z+offset,40);
 }
 torus(g,r*.44,r*.064,cinemaCharcoal,x,y,z,32);
}

function cinemaToyCamera(g,finish){
 box(g,.608,.333,.335,finish,-.094,-.131,0,.064);
 box(g,.397,.124,.032,cinemaCharcoal,-.132,-.135,.175,.022);
 for(const x of [-.251,-.168,-.085])sphere(g,.016,.020,.009,porcelainCream,x,-.137,.195);
 cinemaReel(g,finish,-.238,.177,.035,.198);
 cinemaReel(g,finish,.141,.231,.014,.229);
 disc(g,.129,.240,cinemaCharcoal,.264,-.113,.072);
 disc(g,.157,.065,finish,.264,-.113,.198);
 disc(g,.102,.038,cinemaIceLens,.264,-.113,.234);
 torus(g,.113,.013,porcelainGold,.264,-.113,.246,32);
 g.rotation.set(.19,-.23,-.14);
}

function cinemaSlate(g,finish){
 box(g,.752,.499,.133,finish,0,-.072,0,.054);
 box(g,.641,.382,.013,cinemaCharcoal,0,-.083,.074,.019);
 for(const [y,w] of [[.040,.521],[-.112,.521],[-.187,.310]])box(g,w,.010,.007,porcelainCream,0,y,.084,.004,false);
 const hinge=new THREE.Group();
 hinge.position.set(-.358,.180,0);
 box(hinge,.743,.099,.137,finish,.357,0,0,.019);
 for(let i=0;i<5;i++){
  const x=.010+i*.138;
  const strip=polygon(hinge,[[x,-.043],[x+.060,-.043],[x+.108,.043],[x+.048,.043]],.010,porcelainCream,.070);
  strip.castShadow=false;
 }
 hinge.rotation.z=.174;
 sphere(hinge,.031,.027,.010,porcelainGold,.023,0,.079);
 hinge.updateMatrix();
 for(const mesh of [...hinge.children]){
  mesh.applyMatrix4(hinge.matrix);
  g.add(mesh);
 }
 g.rotation.set(.220,-.189,-.024);
}

function cinemaFoldingChair(g,canvasPaint){
 for(const side of [-1,1]){
  const x=side*.318;
  rod(g,[x,-.355,-.198],[x,.017,.198],.034,toastCrust);
  rod(g,[x,-.355,.198],[x,.260,-.178],.035,toastCrust);
  rod(g,[x,-.022,.180],[x,.192,.160],.024,toastCrust);
  rod(g,[x,.186,.168],[x,.213,-.177],.033,toastCrust);
  sphere(g,.044,.042,.035,porcelainGold,x,-.139,-.021);
 }
 for(const x of [-.300,.300])rod(g,[x,-.041,-.170],[x,.410,-.190],.034,toastCrust);
 box(g,.581,.053,.372,canvasPaint,0,-.038,0,.025);
 box(g,.653,.229,.044,canvasPaint,0,.300,-.172,.032);
 box(g,.515,.019,.009,porcelainCream,0,.355,-.148,.007,false);
 g.rotation.set(.35,-.23,.05);
}

function cinemaColoredGlasses(g,frame){
 for(const side of [-1,1]){
  box(g,.322,.248,.071,frame,side*.201,.022,.022,.052);
  box(g,.243,.169,.021,side<0?cinemaRoseLens:cinemaIceLens,side*.201,.021,.066,.038);
  const glare=box(g,.109,.017,.008,porcelainCream,side*.201-.022,.073,.080,.008);
  glare.rotation.z=.28;
  rod(g,[side*.355,.048,.003],[side*.298,.115,-.286],.024,frame);
  sphere(g,.026,.026,.026,frame,side*.298,.115,-.286);
 }
 box(g,.130,.058,.076,frame,0,.029,.023,.026);
 g.rotation.set(.24,-.18,-.080);
}

function cinemaPopcornCarton(g,finish){
 const cup=lathe(g,[[0,-.435],[.208,-.435],[.232,-.408],[.331,.197],[.322,.218],[.276,.218],[.263,.161]],finish);
 cup.scale.z=.89;
 for(let i=0;i<8;i++){
  const angle=i*Math.PI/4;
  const stripe=polygon(g,[[-.045,-.398],[.045,-.398],[.076,.175],[-.076,.175]],.008,porcelainCream);
  stripe.rotation.y=angle;
  stripe.rotation.x=.160*Math.cos(angle);
  stripe.rotation.z=-.160*Math.sin(angle);
  stripe.position.set(.278*Math.sin(angle),0,.261*Math.cos(angle));
 }
 for(const [x,y,z] of [[-.183,.222,.085],[.187,.215,.082],[0,.271,.163],[-.130,.252,-.090],[.145,.268,-.092],[-.081,.340,.055],[.091,.353,.020],[.003,.395,-.017]]){
  sphere(g,.111,.101,.105,porcelainCream,x,y,z);
  sphere(g,.060,.060,.055,honeyMilk,x+.034,y-.032,z+.067);
 }
 torus(g,.322,.017,finish,0,.218,0,44).rotation.x=Math.PI*.5;
 g.rotation.set(.24,-.22,.06);
}

function cinemaTicket(g,finish){
 const boundary=[[-.424,-.209],[-.074,-.209],[-.043,-.169],[0,-.162],[.043,-.169],[.074,-.209],
  [.424,-.209],[.424,.209],[.074,.209],[.043,.168],[0,.162],[-.043,.168],[-.074,.209],[-.424,.209]];
 polygon(g,boundary,.084,finish,-.039);
 box(g,.418,.276,.017,porcelainCream,-.168,0,.050,.035);
 for(let i=0;i<7;i++){
  sphere(g,.007,.009,.005,mochaBrown,.108,-.165+i*.055,.051);
 }
 for(const [x,w] of [[-.265,.090],[-.160,.052],[-.103,.029],[-.049,.035]]){
  box(g,w,.060,.010,finish,x,.042,.062,.012);
 }
 for(const [y,w] of [[-.031,.312],[-.080,.218]])box(g,w,.010,.010,mochaBrown,-.186,y,.062,.004,false);
 for(const x of [.195,.216,.259,.274,.297,.322,.348])box(g,.010,.149,.010,cinemaCharcoal,x,0,.052,.003,false);
 g.rotation.set(.21,-.28,-.32);
}

const cinemaBuilders={
 'Movie Cam':['玩具电影摄影机',cinemaToyCamera],Clapperboard:['场记板',cinemaSlate],
 'Director Chair':['折叠帆布椅',cinemaFoldingChair],'Movie Glass':['红蓝立体眼镜',cinemaColoredGlasses],
 Megaphone:['手持扩音器',megaphone],'Movie Roll':['电影胶片盘',cinemaReel],
 Popcorn:['爆米花桶',cinemaPopcornCarton],'Movie Ticket':['电影票',cinemaTicket],
};

function cinemaToy([id,label]){
 const split=label.lastIndexOf(' '),family=label.slice(0,split),color=label.slice(split+1);
 const [name,build]=cinemaBuilders[family];
 const finish=color==='Black'?cinemaCharcoal:fairToyPaints.get(color);
 const prefix=color==='Black'?'黑':fairToyColors.get(color);
 return [id,[prefix+'色'+(family==='Movie Glass'?'镜框'+name:name),g=>build(g,finish)]];
}

