const dinosaurIvory=plastic('#fce5a5');
const dinosaurLeaf=plastic('#81a663');
const dinosaurEye=plastic('#362f45');

function dinosaurFeet(g,finish,positions){
 for(const [x,z] of positions){
  sphere(g,.077,.118,.064,finish,x,-.163,z);
  sphere(g,.085,.048,.072,finish,x+.029,-.246,z);
  for(const side of [-1,1])sphere(g,.026,.024,.018,dinosaurIvory,x+.089,-.244,z+side*.030);
 }
}

function dinosaurEyes(g,x,y,z){
 for(const side of [-1,1]){
  sphere(g,.047,.053,.021,dinosaurIvory,x,y,z*side);
  sphere(g,.023,.031,.022,dinosaurEye,x+.012,y-.004,(z+.014)*side);
  sphere(g,.007,.009,.010,porcelainCream,x+.020,y+.006,(z+.032)*side);
 }
}

function hornedDinosaur(g,finish){
 sphere(g,.247,.174,.155,finish,-.095,-.042);
 const tail=sphere(g,.188,.076,.067,finish,-.334,-.063);
 tail.rotation.z=-.28;
 dinosaurFeet(g,finish,[[-.183,-.112],[-.183,.112],[.073,-.112],[.073,.112]]);
 sphere(g,.080,.193,.188,dinosaurLeaf,.100,.084);
 for(let i=0;i<7;i++){
  const angle=-Math.PI*.16+i*Math.PI*.216;
  sphere(g,.063,.043,.040,dinosaurLeaf,.116,.081+.163*Math.sin(angle),.165*Math.cos(angle));
 }
 sphere(g,.180,.104,.123,finish,.232,.036);
 sphere(g,.080,.045,.075,dinosaurIvory,.360,.002);
 for(const side of [-1,1]){
  const horn=add(g,new THREE.ConeGeometry(.045,.135,12),dinosaurIvory,.245,.161,side*.092);
  horn.rotation.z=-.48;
 }
 dinosaurEyes(g,.242,.075,.112);
}

function platedDinosaur(g,finish){
 sphere(g,.298,.166,.143,finish,-.057,-.061);
 const tail=sphere(g,.171,.058,.053,finish,-.356,-.036);
 tail.rotation.z=-.27;
 const head=sphere(g,.151,.081,.078,finish,.288,-.106);
 head.rotation.z=-.35;
 dinosaurFeet(g,finish,[[-.207,-.103],[-.207,.103],[.126,-.094],[.126,.094]]);
 for(const [x,y,h] of [[-.349,.028,.082],[-.234,.066,.123],[-.108,.096,.175],[.029,.105,.183],[.156,.089,.119]]){
  polygon(g,[[x-.061,y],[x-.040,y+h*.68],[x+.006,y+h],[x+.054,y+h*.58],[x+.068,y]],.045,dinosaurIvory,-.023);
 }
 dinosaurEyes(g,.325,-.094,.072);
}

function walkingDinosaur(g,finish){
 sphere(g,.176,.221,.143,finish,-.060,-.032);
 sphere(g,.117,.153,.113,dinosaurIvory,.018,-.058);
 const tail=sphere(g,.220,.080,.073,finish,-.253,-.054);
 tail.rotation.z=-.32;
 const neck=sphere(g,.114,.166,.111,finish,.080,.068);
 neck.rotation.z=-.62;
 sphere(g,.179,.129,.132,finish,.176,.174);
 box(g,.242,.089,.190,finish,.225,.108,0,.042);
 box(g,.147,.014,.015,dinosaurEye,.252,.126,.095,.006,false);
 for(const side of [-1,1]){
  sphere(g,.074,.120,.064,finish,-.078,-.169,side*.106);
  sphere(g,.104,.046,.078,finish,-.030,-.263,side*.122);
  rod(g,[.046,-.013,side*.106],[.171,-.070,side*.128],.032,finish);
  sphere(g,.048,.034,.035,finish,.164,-.072,side*.128);
  for(const dx of [.012,.044])sphere(g,.022,.021,.018,dinosaurIvory,dx,-.261,side*.131);
 }
 dinosaurEyes(g,.207,.196,.120);
}

function hatchingDinosaur(g,finish){
 sphere(g,.184,.220,.149,finish,0,-.042,0);
 sphere(g,.194,.145,.153,finish,.041,.192,.010);
 sphere(g,.108,.073,.109,finish,.139,.131,.024);
 dinosaurEyes(g,.092,.219,.137);
 for(const side of [-1,1]){
  sphere(g,.013,.017,.011,dinosaurEye,.218,.146,side*.077);
  sphere(g,.074,.036,.056,finish,side*.111,-.049,.128).rotation.z=side*.23;
 }
 const shell=lathe(g,[[0,-.337],[.093,-.332],[.161,-.289],[.212,-.217],[.233,-.129],[.238,-.045],
  [.225,-.045],[.223,-.128],[.203,-.213],[.147,-.278],[.091,-.316],[0,-.323]],dinosaurIvory);
 shell.scale.z=.85;
 for(let i=0;i<9;i++){
  const angle=i*Math.PI*2/9;
  const rim=polygon(g,[[-.066,-.060],[.041,-.060],[.024,.014+i%2*.023]],.026,dinosaurIvory);
  rim.rotation.y=angle;
  rim.position.set(.224*Math.sin(angle),0,.193*Math.cos(angle));
 }
 for(const [x,y] of [[-.093,-.134],[.086,-.185],[.023,-.248]]){
  const z=.186*Math.sqrt(1-(x/.23)**2-(Math.max(0,-y-.083)/.285)**2);
  sphere(g,.036,.028,.015,dinosaurLeaf,x,y,z);
 }
}

function flyingDinosaur(g,finish){
 sphere(g,.116,.200,.100,finish,0,-.026);
 for(const side of [-1,1]){
  const wing=polygon(g,[[side*.050,.055],[side*.245,.189],[side*.428,.303],[side*.397,.123],[side*.315,-.040],[side*.093,-.128]],
   .045,finish,-.025);
  wing.rotation.y=side*.13;
  rod(g,[side*.074,-.070,.031],[side*.290,.106,.034],.013,dinosaurIvory);
 }
 sphere(g,.076,.107,.091,finish,0,.173,.040);
 polygon(g,[[-.035,.250],[.035,.250],[.009,.366],[-.054,.336]],.040,dinosaurLeaf,-.021);
 box(g,.069,.123,.097,dinosaurIvory,0,.245,.100,.033);
 for(const side of [-1,1])sphere(g,.016,.026,.025,dinosaurEye,side*.059,.206,.092);
}

function dinosaurFootprint(g,finish){
 disc(g,.337,.145,finish);
 torus(g,.289,.016,dinosaurIvory,0,0,.085,32);
 sphere(g,.108,.112,.020,dinosaurLeaf,0,-.105,.085);
 for(const [x,y,angle] of [[-.095,.027,.56],[0,.104,0],[.095,.027,-.56]]){
  sphere(g,.040,.121,.022,dinosaurLeaf,x,y,.089).rotation.z=angle;
 }
}

function dinosaurEgg(g,finish){
 sphere(g,.238,.308,.218,finish);
 for(const [x,y,scale] of [[-.076,.116,.043],[.081,.164,.029],[.065,-.062,.057],[-.119,-.072,.045],[.024,-.208,.031]]){
  const z=.211*Math.sqrt(1-(x/.238)**2-(y/.308)**2);
  for(const side of [-1,1]){
   const spot=sphere(g,scale,scale*.87,.012,dinosaurIvory,x,y,z*side);
   spot.rotation.set(-side*y*3,side*x*4,0);
  }
 }
}

function dinosaurSkeleton(g){
 const bone=dinosaurIvory;
 for(const [a,b] of [
  [[-.300,-.053,0],[-.082,-.019,0]],[[-.082,-.019,0],[.113,-.036,0]],
  [[.113,-.036,0],[.181,.132,0]],[[.181,.132,0],[.347,.132,0]],
  [[-.082,-.019,0],[-.152,-.173,0]],[[-.152,-.173,0],[-.039,-.217,0]],
  [[.081,-.036,0],[.182,-.093,0]],
 ])rod(g,a,b,.029,bone);
 sphere(g,.106,.076,.066,bone,.265,.150);
 sphere(g,.038,.045,.017,dinosaurEye,.251,.175,.060);
 for(let i=0;i<4;i++){
  const x=-.113+i*.050;
  for(const side of [-1,1])rod(g,[x,-.010,0],[x+.007,-.106,side*.063],.024,bone);
 }
 for(const x of [-.294,-.240,-.189,-.133,-.081,-.028,.032]){
  sphere(g,.030,.032,.036,bone,x,-.027);
 }
}

const dinosaurModels={
 'Triceratops':['三角龙玩偶',hornedDinosaur],
 'Stegosaurus':['剑龙玩偶',platedDinosaur],
 'Dino Skeleton':['恐龙骨架',dinosaurSkeleton],
 'Rex':['霸王龙玩偶',walkingDinosaur],
 'Pteranodon':['翼龙玩偶',flyingDinosaur],
 'Footprint':['恐龙脚印徽章',dinosaurFootprint],
 'Dino Egg':['斑点恐龙蛋',dinosaurEgg],
 'Baby Dino':['破壳小恐龙',hatchingDinosaur],
};
function dinosaurToy([id,label]){
 const split=label.lastIndexOf(' ');
 const [name,build]=dinosaurModels[label.slice(0,split)];
 const color=label.slice(split+1);
 const finish=color==='White'?ceramicIvory:keepsakeFinishes.get(color);
 const prefix=color==='White'?'白':keepsakeColors.get(color);
 return [id,[prefix+'色'+name,g=>{
  build(g,finish);
  g.rotation.set(.21,-.32,.07);
 }]];
}

function straightToyLetter(g,strokes,finish){
 const points=new Map();
 for(const [first,second] of strokes){
  rod(g,[...first,0],[...second,0],.091,finish);
  points.set(first.join(','),first);
  points.set(second.join(','),second);
 }
 for(const [x,y] of points.values())sphere(g,.091,.091,.091,finish,x,y);
 g.rotation.set(.17,-.21,.08);
}

