const summerIce=plastic('#68b8cb');
const summerInk=plastic('#393447');
const summerMist=plastic('#edf3da');
const summerStripes=[paradeRed,musicOrange,paradeGold,gardenGreen,fleetBlue,toyPurple,toyPink];

function summerSnorkel(g,finish){
 const curve=new THREE.Path();
 curve.moveTo(-.152,.338);
 curve.lineTo(-.152,-.185);
 curve.bezierCurveTo(-.152,-.358,.182,-.415,.182,-.208);
 curve.lineTo(.182,-.105);
 const points=curve.getPoints(18).map(({x,y})=>new THREE.Vector3(x,y,0));
 add(g,new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),30,.054,10,false),finish);
 box(g,.153,.124,.144,summerInk,-.151,.316,0,.046);
 box(g,.200,.084,.136,summerInk,.198,-.097,0,.032);
 for(const y of [.116,.182,.246])torus(g,.057,.015,summerMist,-.152,y,0,22).rotation.x=Math.PI/2;
}

function summerSunbed(g,finish,striped){
 for(const x of [-.233,.233]){
  rod(g,[x,-.363,-.104],[x,-.363,-.234],.022,summerMist);
  rod(g,[x,.242,-.105],[x,.215,-.234],.022,summerMist);
  rod(g,[x,-.363,-.232],[x,.217,-.232],.018,summerMist);
 }
 box(g,.532,.529,.094,finish,0,-.170,-.019,.055);
 const back=box(g,.532,.338,.092,finish,0,.238,.062,.055);
 back.rotation.x=.51;
 for(let i=0;i<5;i++){
  const x=(i-2)*.083;
  const color=striped?summerStripes[i]:summerMist;
  box(g,.025,.445,.012,color,x,-.171,.035,.005,false);
  box(g,.025,.251,.012,color,x,.223,.106,.005,false).rotation.x=.51;
 }
 box(g,.434,.056,.126,summerMist,0,-.386,-.018,.021);
}

function summerSunglasses(g,finish){
 for(const side of [-1,1]){
  const x=side*.191;
  const lens=box(g,.300,.209,.041,summerIce,x,.018,.052,.072);
  lens.rotation.z=side*.075;
  for(const [size,dy] of [[.292,.103],[.248,-.068]])box(g,size,.032,.074,finish,x,dy,.048,.014);
  for(const offset of [-.134,.134])box(g,.037,.176,.078,finish,x+offset,.015,.051,.016);
  const earpiece=box(g,.039,.298,.052,finish,side*.341,-.121,-.008,.017);
  earpiece.rotation.z=side*.29;
  earpiece.rotation.x=.55;
  box(g,.092,.012,.011,summerMist,x-.027,.059,.081,.006,false).rotation.z=.38;
 }
 torus(g,.076,.019,finish,0,.021,.044,22);
}

function summerSunscreen(g,finish){
 const body=box(g,.422,.557,.190,finish,0,.057,0,.065);
 body.rotation.z=-.065;
 box(g,.341,.060,.183,summerMist,-.015,.311,.001,.023);
 box(g,.318,.153,.181,summerMist,.016,-.276,0,.048);
 box(g,.294,.273,.017,summerMist,.007,.035,.105,.042);
 disc(g,.064,.016,paradeGold,.007,.063,.129);
 for(let i=0;i<8;i++){
  const a=i*Math.PI/4;
  sphere(g,.017,.017,.008,musicOrange,.007+.092*Math.cos(a),.063+.092*Math.sin(a),.131);
 }
 box(g,.099,.013,.012,summerIce,.008,-.069,.129,.004);
}

function summerCanopyPoint(sector,fraction,reach){
 const angle=(sector+fraction)*Math.PI/4;
 const scallop=Math.sin(fraction*Math.PI);
 const radius=(.395+.014*scallop)*reach;
 const height=.273-.294*Math.pow(reach,1.6)-.020*scallop*reach*reach;
 return [radius*Math.cos(angle),height,.022+radius*Math.sin(angle)];
}

function summerParasol(g,finish,striped){
 const segments=8;
 for(let sector=0;sector<8;sector++){
  const paint=striped?summerStripes[sector%summerStripes.length]:sector%2?summerMist:finish;
  const fabric=paint.clone();
  fabric.side=THREE.DoubleSide;
  const vertices=[],indices=[];
  for(let row=0;row<=segments;row++){
   const reach=.045+.955*row/segments;
   for(let column=0;column<=segments;column++)vertices.push(...summerCanopyPoint(sector,column/segments,reach));
  }
  const stride=segments+1;
  for(let row=0;row<segments;row++)for(let col=0;col<segments;col++){
   const point=row*stride+col;
   indices.push(point,point+1,point+stride,point+1,point+stride+1,point+stride);
  }
  const panel=new THREE.BufferGeometry();
  panel.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));
  panel.setIndex(indices);
  panel.computeVertexNormals();
  add(g,panel,fabric);
  const seam=Array.from({length:6},(_,i)=>summerCanopyPoint(sector,0,.075+i*.185));
  const piping=Array.from({length:9},(_,i)=>summerCanopyPoint(sector,i/8,1));
  moldedCurve(g,seam,.0075,summerMist,17);
  moldedCurve(g,piping,.011,paint,18);
 }
 sphere(g,.035,.036,.036,porcelainGold,0,.283,.022);
 rod(g,[0,-.419,.022],[0,.263,.022],.028,summerMist);
 rod(g,[0,-.411,.022],[0,-.305,.022],.035,finish);
}

function summerSwimRing(g,finish,striped){
 torus(g,.275,.100,finish,0,0,0,40);
 for(let i=0;i<4;i++){
  const band=add(g,new THREE.TorusGeometry(.278,.102,10,9,.54),striped?summerStripes[i+1]:summerMist);
  band.rotation.z=i*Math.PI/2+.40;
 }
 sphere(g,.035,.041,.031,finish,0,.338,.082);
}

function summerFlipFlop(g,finish,striped){
 const foot=box(g,.327,.714,.096,finish,0,0,0,.142);
 foot.rotation.z=-.17;
 const pad=box(g,.289,.650,.037,striped?fleetBlue:summerMist,0,.004,.054,.127);
 pad.rotation.z=-.17;
 for(const [a,b] of [[[-.071,.207,.107],[-.122,.016,.085]],[[-.071,.207,.107],[.155,.040,.085]]])rod(g,a,b,.032,finish);
 sphere(g,.035,.034,.041,finish,-.071,.207,.104);
 for(const y of [-.247,-.194,-.141])box(g,.164,.014,.017,striped?summerMist:finish,y*-.15,y,.078,.005).rotation.z=-.17;
}

function summerSandBucket(g,finish){
 const shape=new THREE.LatheGeometry([
  new THREE.Vector2(0,-.253),new THREE.Vector2(.204,-.253),new THREE.Vector2(.224,-.231),
  new THREE.Vector2(.302,.176),new THREE.Vector2(.314,.187),new THREE.Vector2(.318,.212),
  new THREE.Vector2(.295,.224),new THREE.Vector2(.275,.206),new THREE.Vector2(.203,-.215),
  new THREE.Vector2(0,-.215),
 ],32);
 add(g,shape,finish);
 torus(g,.297,.022,summerMist,0,.199,0,32).rotation.x=Math.PI/2;
 torus(g,.216,.015,summerMist,0,-.223,0,32).rotation.x=Math.PI/2;
 for(const side of [-1,1]){
  const star=Array.from({length:10},(_,i)=>{
   const angle=Math.PI*.5+i*Math.PI*.2;
   const radius=i%2?.044:.095;
   return [Math.cos(angle)*radius,-.038+Math.sin(angle)*radius];
  });
  const badge=polygon(g,star,.014,summerMist,side*.260-.007);
  badge.rotation.x=side*-.15;
 }

 const handle=add(g,new THREE.TorusGeometry(.285,.025,8,32,Math.PI),paradeGold,0,.109,0);
 handle.rotation.y=.45;
 for(const side of [-1,1])sphere(g,.043,.043,.043,paradeGold,side*.279,.121,side*-.06);
}
