const craftSatin=plastic('#fff0cb');
const craftInk=plastic('#393445');
const craftWood=plastic('#aa734e');
const craftLionCream=plastic('#ffd993');
const craftFanPrints=new Map([
 ['Black',0],['Blue',1],['Green',2],['Orange',3],['Pink',4],['Red',5],['White',6],['Yellow',7],
]);

function craftFestivalDoll(g,finish){
 playroomDoll(g,finish,false);
 const hatBand=box(g,.215,.050,.105,porcelainGold,.018,.333,.101,.023);
 hatBand.rotation.z=-.04;
 box(g,.177,.064,.025,paradeRed,0,-.046,.128,.018);
 for(const y of [-.047,-.113,-.178]){
  rod(g,[-.048,y,.130],[.048,y,.130],.010,porcelainGold);
  sphere(g,.015,.015,.011,porcelainGold,.023,y,.145);
 }
}

function craftFoldingFan(g,finish,color){
 foldingFan(g,finish,craftFanPrints.get(color));
 torus(g,.044,.009,porcelainGold,0,-.293,.051,20);
 rod(g,[0,-.326,.042],[.030,-.391,.045],.008,porcelainGold);
 for(let i=0;i<5;i++)rod(g,[.030,-.388,.045],[.004+i*.013,-.459,.043],.005,paradeRed);
 g.rotation.set(.22,-.18,-.23);
}

function craftPaperCrane(g,finish){
 const body=[[-.143,-.104],[-.177,.074],[-.022,.169],[.151,.082],[.166,-.093],[.033,-.195]];
 polygon(g,body,.090,finish,-.040);
 for(const side of [-1,1]){
  const wing=polygon(g,[[side*.031,.036],[side*.410,.244],[side*.356,-.030],[side*.145,-.131]],
   .016,finish,-.012);
  wing.rotation.y=side*.57;
  rod(g,[side*.064,-.021,.010],[side*.310,.124,-.178],.009,craftSatin);
 }
 const neck=polygon(g,[[.077,.117],[.117,.362],[.241,.294],[.161,.281],[.146,.067]],.038,finish,.040);
 neck.rotation.y=-.20;
 polygon(g,[[-.279,.162],[-.131,.049],[-.082,-.051],[-.246,-.028]],.031,finish,-.041);
 g.rotation.set(.37,-.48,-.09);
}

function craftLionToy(g,finish){
 sphere(g,.199,.202,.179,finish,0,-.129);
 sphere(g,.266,.222,.179,finish,0,.119,.043);
 for(const side of [-1,1]){
  sphere(g,.096,.088,.066,finish,side*.215,.263,.038);
  sphere(g,.049,.050,.031,craftLionCream,side*.224,.268,.094);
  sphere(g,.075,.068,.044,craftLionCream,side*.102,.151,.191);
  sphere(g,.036,.040,.019,craftInk,side*.099,.157,.230);
  sphere(g,.014,.016,.010,craftSatin,side*.109,.172,.246);
  sphere(g,.105,.058,.089,finish,side*.104,-.289,.074);
  for(const x of [.146,.19,.230])sphere(g,.051,.038,.024,craftLionCream,side*x,.032,.173);
 }
 sphere(g,.151,.041,.046,paradeRed,0,-.018,.170);
 sphere(g,.057,.035,.032,porcelainGold,0,.052,.222);
 disc(g,.048,.025,porcelainGold,0,.250,.189);
 g.rotation.set(.22,-.24,.05);
}

function craftWoodenClog(g,finish){
 const sole=box(g,.351,.679,.173,craftWood,0,0,-.050,.110);
 sole.rotation.z=-.13;
 const footbed=box(g,.330,.656,.057,finish,0,0,.047,.093);
 footbed.rotation.z=-.13;
 for(const y of [-.201,.157])box(g,.302,.106,.103,craftWood,y*-.13,y,-.180,.025);
 for(const side of [-1,1]){
  moldedCurve(g,[[.013,.223,.087],[side*.067,.141,.169],[side*.139,.042,.149],[side*.142,-.022,.081]],.026,craftSatin);
 }
 g.rotation.set(.47,-.25,.22);
}

function craftTaiji(g,finish){
 const ring=.312;
 disc(g,.365,.148,porcelainGold);
 for(const side of [-1,1]){
  const bright=new THREE.Shape();
  bright.absarc(0,0,ring,Math.PI*.5,Math.PI*1.5,false);
  bright.absarc(0,-ring*.5,ring*.5,-Math.PI*.5,Math.PI*.5,false);
  bright.absarc(0,ring*.5,ring*.5,-Math.PI*.5,Math.PI*.5,true);
  bright.closePath();
  disc(g,ring,.017,finish,0,0,side*.081);
  const face=add(g,new THREE.ExtrudeGeometry(bright,{depth:.009,bevelEnabled:false,curveSegments:24}),craftSatin,0,0,side*.091);
  face.rotation.y=side===1?0:Math.PI;
  disc(g,.048,.013,craftSatin,0,ring*.50,side*.104);
  disc(g,.048,.013,finish,0,-ring*.50,side*.104);
 }
 g.rotation.set(.32,-.29,-.22);
}

const craftModels={
 'Asian Doll':['节庆布娃娃',craftFestivalDoll],
 'Folding Fan':['折扇',craftFoldingFan],
 Katana:['泡棉练功剑',fairFoamSword],
 Maneki:['招财猫摆件',(g,finish)=>marketPorcelainAnimal(g,finish,true)],
 Origami:['折纸鹤',craftPaperCrane],
 Sumo:['醒狮玩偶',craftLionToy],
 'Wood Shoes':['木屐玩具',craftWoodenClog],
 'Ying Yang':['太极木牌',craftTaiji],
};
function craftToy([id,label]){
 const split=label.lastIndexOf(' ');
 const [name,build]=craftModels[label.slice(0,split)];
 const color=label.slice(split+1);
 const alternate={White:[craftSatin,'白'],Black:[craftInk,'黑']};
 const [finish,prefix]=alternate[color]??[keepsakeFinishes.get(color),keepsakeColors.get(color)];
 return [id,[prefix+'色'+name,g=>build(g,finish,color)]];
}

