const campsiteCloth=plastic('#e9ce97');
const campsiteHardware=plastic('#48505d');
const campsiteAluminum=plastic('#b4bcca');
const campsiteSpectrum=[paradeRed,musicOrange,paradeGold,gardenGreen,fleetBlue,toyPurple];

function campingToyAxe(g,finish){
 rod(g,[.015,-.379,0],[.015,.251,0],.059,toastCrust);
 sphere(g,.084,.101,.080,finish,.015,-.341);
 const head=[[-.317,.134],[-.293,.350],[-.142,.282],[.160,.277],[.160,.159],[-.129,.131]];
 polygon(g,head,.086,finish,-.042);
 polygon(g,[[-.317,.134],[-.293,.350],[-.243,.326],[-.260,.154]],.094,campsiteAluminum,-.045);
 box(g,.058,.146,.100,campsiteHardware,.082,.222,0,.022);
 for(const y of [-.355,-.315,-.275])torus(g,.068,.013,campsiteCloth,.015,y,0,22).rotation.x=Math.PI/2;
 g.rotation.set(.22,-.20,-.38);
}

function campingToyBag(g,finish){
 schoolBackpack(g,finish,campsiteCloth);
 box(g,.113,.280,.135,campsiteCloth,.307,-.033,.066,.046).rotation.z=-.14;
 box(g,.120,.062,.141,finish,.318,.071,.067,.025).rotation.z=-.14;
 box(g,.098,.044,.020,campsiteHardware,0,.099,.272,.011);
 disc(g,.025,.009,porcelainGold,0,.099,.281);
 g.rotation.set(.24,-.21,-.10);
}

function campingToyFlask(g,finish){
 lathe(g,[[0,-.343],[.213,-.343],[.228,-.313],[.228,.224],[.205,.267],[.173,.286],[.162,.340],[0,.340]],finish);
 lathe(g,[[0,.242],[.180,.242],[.183,.264],[.183,.372],[.162,.394],[0,.394]],campsiteAluminum);
 torus(g,.217,.013,campsiteCloth,0,-.247,0,36).rotation.x=Math.PI/2;
 torus(g,.217,.013,campsiteCloth,0,.186,0,36).rotation.x=Math.PI/2;
 const loop=torus(g,.115,.023,campsiteHardware,.207,.163,0,32);
 loop.scale.set(.69,1.03,1);
 box(g,.133,.097,.015,campsiteCloth,0,-.066,.230,.023);
 sphere(g,.043,.034,.011,porcelainGold,0,-.069,.238);
 g.rotation.set(.27,-.32,-.44);
}

function campingToyMatch(g,finish,rainbow){
 const cup=box(g,.453,.565,.152,finish,0,-.144,0,.045);
 cup.rotation.z=-.09;
 box(g,.327,.390,.021,campsiteCloth,.006,-.121,.085,.033);
 for(let i=0;i<4;i++){
  const x=(i-1.5)*.098;
  const wood=rod(g,[x,-.180,.029],[x+.022,.273,.029],.023,toastCrust);
  wood.castShadow=true;
  sphere(g,.041,.055,.041,rainbow?campsiteSpectrum[i]:paradeRed,x+.022,.300,.029);
 }
 box(g,.329,.068,.012,campsiteHardware,.012,-.250,.104,.012);
 g.rotation.set(.25,-.32,.09);
}

function campingToyCarabiner(g,finish){
 const outline=new THREE.Path();
 outline.moveTo(.170,-.203);
 outline.bezierCurveTo(.101,-.411,-.120,-.400,-.220,-.188);
 outline.bezierCurveTo(-.264,-.022,-.236,.245,-.148,.334);
 outline.bezierCurveTo(-.038,.445,.233,.375,.252,.229);
 outline.lineTo(.217,.145);
 const points=outline.getPoints(17).map(({x,y})=>new THREE.Vector3(x,y,0));
 add(g,new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),42,.058,12,false),finish);
 rod(g,[.170,-.203,0],[.217,.145,0],.038,campsiteHardware);
 rod(g,[.197,-.033,0],[.218,.095,0],.047,campsiteAluminum);
 for(let i=0;i<4;i++)torus(g,.046,.007,campsiteHardware,.198+i*.004,-.023+i*.027,0,18).rotation.x=Math.PI/2;
 g.rotation.set(.23,-.22,.42);
}

function campingToyStove(g,finish){
 const base=box(g,.668,.168,.459,finish,0,-.112,0,.078);
 base.rotation.y=.072;
 for(const x of [-.245,.245])for(const z of [-.161,.161])box(g,.089,.072,.082,campsiteHardware,x,-.214,z,.032);
 for(const radii of [[0,.134],[.030,.101],[.054,.058]]){
  const ring=torus(g,radii[1],.019,campsiteHardware,-.103,radii[0]-.025,0,32);
  ring.rotation.x=Math.PI/2;
 }
 for(const [x,z] of [[-.275,0],[-.103,.174],[.068,0],[-.103,-.174]]){
  sphere(g,.036,.033,.030,campsiteAluminum,x,.007,z);
 }
 disc(g,.057,.052,campsiteHardware,.201,-.083,.240);
 box(g,.013,.054,.013,campsiteCloth,.206,-.073,.272,.004);
 g.rotation.set(.69,-.38,.04);
}

function campingToyMarshmallow(g,finish){
 rod(g,[-.069,-.363,-.020],[.031,.340,.001],.021,toastCrust);
 for(const [index,y] of [-.116,.047,.207].entries()){
  const puff=box(g,.327,.173,.291,index===1?ceramicIvory:finish,y*.112,y,0,.068);
  puff.rotation.z=index*.18-.13;
  if(index!==1)for(const angle of [1.0,2.8,4.5]){
   sphere(g,.028,.013,.014,paradeGold,.092*Math.cos(angle),y+.046,.144+.011*Math.sin(angle));
  }
 }
 g.rotation.set(.30,-.18,.46);
}

function campingToyTent(g,finish){
 const groundsheet=finish.clone();
 groundsheet.color.multiplyScalar(.70);
 const tentOutline=[[-.378,-.227],[-.300,.021],[0,.306],[.305,.014],[.374,-.227]];
 polygon(g,tentOutline,.564,finish,-.282);
 box(g,.735,.052,.560,groundsheet,0,-.220,0,.075);
 const door=[[-.171,-.178],[-.136,-.048],[-.089,.071],[0,.177],[.089,.071],[.136,-.048],[.171,-.178]];
 for(const side of [-1,1]){
  const panel=side*.297;
  polygon(g,door,.011,campsiteHardware,panel-.005);
  const zip=door.map(([x,y])=>[x,y,side*.314]);
  moldedCurve(g,zip,.0095,campsiteCloth,27);
  rod(g,[0,-.168,side*.310],[0,.136,side*.310],.006,campsiteAluminum);
  box(g,.027,.036,.022,campsiteCloth,.015,.017,side*.319,.009);
  for(const x of [-.262,.262]){
   const peg=sphere(g,.038,.024,.027,porcelainGold,x,-.209,side*.292);
   peg.rotation.z=x*.27;
  }
 }
 for(const side of [-1,1]){
  for(const z of [-.265,.263]){
   moldedCurve(g,[[0,.320,z],[side*.297,.038,z],[side*.370,-.182,z]],.012,campsiteCloth,16);
  }
  rod(g,[side*.291,.046,-.229],[side*.291,.046,.229],.010,groundsheet);
  rod(g,[side*.358,-.162,-.265],[side*.358,-.162,.265],.010,campsiteCloth);
 }
 rod(g,[0,.320,-.251],[0,.320,.251],.011,groundsheet);
 g.rotation.set(.27,-.31,.08);
}

const campingModels={
 'Camping Axe':['露营玩具斧',campingToyAxe],
 'Camping Bag':['登山包',campingToyBag],
 'Camping Flask':['保温壶',campingToyFlask],
 'Camping Match':['盒装露营火柴',campingToyMatch],
 Carabin:['登山扣',campingToyCarabiner],
 'Gas Stove':['迷你卡式炉',campingToyStove],
 Marshmallow:['烤棉花糖串',campingToyMarshmallow],
 Tent:['帐篷',campingToyTent],
};
function campingToy([id,label]){
 const split=label.lastIndexOf(' ');
 const [name,build]=campingModels[label.slice(0,split)];
 const color=label.slice(split+1);
 const alternate={White:[ceramicIvory,'白'],Black:[campsiteHardware,'黑'],Colorful:[toyPink,'彩']};
 const [finish,prefix]=alternate[color]??[keepsakeFinishes.get(color),keepsakeColors.get(color)];
 return [id,[prefix+'色'+name,g=>build(g,finish,color==='Colorful')]];
}

