const retroCharcoal=plastic('#343247');
const retroCream=plastic('#f3dfad');
const retroScreen=plastic('#608fa1');
const retroKeys=plastic('#a9c7c4');

function retroArcade(g,finish){
 const frame=[[-.277,-.398],[-.273,.320],[-.222,.396],[.227,.396],[.279,.320],[.264,-.398]];
 polygon(g,frame,.421,finish,-.220);
 box(g,.458,.260,.078,retroCharcoal,0,.161,.201,.072);
 box(g,.356,.179,.047,retroScreen,0,.163,.252,.054);
 for(const [x,y] of [[-.102,.175],[-.055,.175],[.090,.118],[.037,.118]]){
  box(g,.024,.020,.013,retroCream,x,y,.278,.006);
 }
 box(g,.465,.118,.236,retroCream,0,-.099,.256,.049);
 rod(g,[-.128,-.072,.348],[-.128,.003,.375],.022,retroCharcoal);
 sphere(g,.042,.044,.041,paradeRed,-.128,.012,.379);
 for(const [x,paint] of [[.042,paradeGold],[.141,gardenGreen]])sphere(g,.031,.020,.029,paint,x,-.045,.359);
 box(g,.092,.075,.010,retroCharcoal,0,-.255,.217,.012);
 g.rotation.set(.31,-.37,.06);
}

function retroCassette(g,finish){
 box(g,.752,.483,.156,finish,0,0,0,.058);
 for(const side of [-1,1]){
  const face=side*.087;
  box(g,.638,.130,.028,retroCream,0,.117,face,.027);
  box(g,.504,.019,.011,finish,0,.143,side*.108,.005,false);
  box(g,.218,.012,.010,retroScreen,-.131,.106,side*.108,.004,false);
  box(g,.385,.117,.029,retroCharcoal,0,-.031,face,.026);
  box(g,.210,.022,.010,retroScreen,0,-.031,side*.106,.006,false);
  for(const x of [-.114,.114]){
   disc(g,.050,.018,retroCream,x,-.031,side*.108);
   disc(g,.021,.017,retroCharcoal,x,-.031,side*.120);
   for(let tooth=0;tooth<5;tooth++){
    const angle=tooth*Math.PI*.4;
    disc(g,.006,.006,retroCream,x+.019*Math.cos(angle),-.031+.019*Math.sin(angle),side*.132);
   }
  }
  for(const x of [-.300,.300]){
   disc(g,.016,.007,campsiteAluminum,x,-.130,side*.087);
   box(g,.018,.004,.006,retroCharcoal,x,-.130,side*.093,.002,false).rotation.z=.49;
  }
  box(g,.300,.052,.013,retroCharcoal,0,-.196,face,.006);
  box(g,.180,.015,.011,retroCream,0,-.197,side*.101,.004,false);
 }
 g.rotation.set(.23,-.20,-.35);
}

function retroDeskClock(g,finish){
 box(g,.648,.471,.260,finish,0,-.036,0,.137);
 box(g,.526,.267,.034,retroCharcoal,0,-.007,.139,.056);
 for(const [index,value] of [0,8,3,0].entries()){
  const x=-.152+index*.101+(index>1?.023:0);
  for(const key of digitStrokes[value]){
   const [a,b]=digitSegments[key].map(([sx,sy])=>[x+sx*.23,sy*.43,.164]);
   rod(g,a,b,.011,retroKeys);
  }
 }
 for(const y of [-.029,.027])sphere(g,.010,.010,.010,retroKeys,.005,y,.165);
 box(g,.198,.050,.087,retroCream,0,.221,0,.018);
 g.rotation.set(.23,-.17,.08);
}

function retroFloppy(g,finish){
 const edge=[[-.324,-.318],[-.324,.329],[.248,.329],[.328,.250],[.328,-.318]];
 polygon(g,edge,.084,finish,-.043);
 for(const side of [-1,1]){
  box(g,.430,.202,.027,campsiteAluminum,0,.217,side*.048,.018);
  box(g,.115,.125,.012,retroCharcoal,.072,.220,side*.061,.008);
  box(g,.479,.248,.015,retroCream,0,-.135,side*.049,.023);
  for(const y of [-.073,-.141,-.184])box(g,.304,.012,.011,retroScreen,-.045,y,side*.062,.004);
 }
 g.rotation.set(.29,-.22,-.25);
}

function retroRecord(g,finish){
 disc(g,.380,.066,retroCharcoal);
 for(const side of [-1,1]){
  for(const radius of [.191,.239,.288,.338])torus(g,radius,.006,retroScreen,0,0,side*.037,50);
  disc(g,.151,.023,finish,0,0,side*.043);
  disc(g,.032,.018,retroCream,0,0,side*.059);
 }
 g.rotation.set(.37,-.20,-.26);
}

function retroGramophone(g,finish){
 box(g,.628,.248,.482,finish,0,-.247,0,.070);
 const deck=disc(g,.157,.040,retroCharcoal,-.151,-.105,.059);
 deck.rotation.x=Math.PI/2;
 moldedCurve(g,[[.165,-.132,-.092],[.194,.043,-.056],[.139,.163,.011],[.059,.191,.106]],.039,porcelainGold);
 const horn=lathe(g,[[.033,-.102],[.073,-.045],[.129,.014],[.207,.100],[.238,.152]],porcelainGold);
 horn.rotation.set(.95,0,.53);
 horn.position.set(-.018,.194,.155);
 const lip=torus(g,.235,.017,retroCream,-.081,.271,.253,38);
 lip.rotation.set(2.52,0,.53);
 g.rotation.set(.20,-.30,.03);
}

function retroHandheld(g,finish){
 box(g,.411,.628,.162,finish,0,-.015,0,.084);
 box(g,.318,.222,.027,retroCharcoal,0,.115,.093,.032);
 box(g,.270,.162,.023,retroScreen,0,.115,.111,.025);
 for(const y of [.064,.115,.159])box(g,.144,.011,.008,retroKeys,0,y,.128,.005);
 disc(g,.090,.024,retroCream,0,-.121,.108);
 disc(g,.037,.019,finish,0,-.121,.123);
 rod(g,[.107,.286,.010],[.123,.354,.032],.028,retroCharcoal);
 g.rotation.set(.28,-.34,.22);
}

function retroTypewriter(g,finish){
 box(g,.721,.259,.485,finish,0,-.178,.010,.070);
 box(g,.665,.172,.342,finish,0,-.023,-.085,.047);
 box(g,.472,.269,.029,retroCream,0,.182,-.175,.018).rotation.x=-.12;
 for(const y of [.116,.166,.218])box(g,.262,.012,.015,retroScreen,-.046,y,-.150,.004);
 for(const row of [0,1,2])for(let index=0;index<7;index++){
  const x=(index-3)*.081,y=-.071+row*.046,z=.226-row*.075;
  disc(g,.026,.035,retroCharcoal,x,y,z).rotation.x=Math.PI/2;
 }
 box(g,.303,.030,.063,retroCharcoal,0,-.052,.225,.020);
 rod(g,[.272,.061,-.075],[.365,.107,-.070],.024,porcelainGold);
 g.rotation.set(.73,-.26,.05);
}
const retroModels={
 'Arcade Machine':['街机',retroArcade],
 'Casette Tape':['录音磁带',retroCassette],
 Clock:['电子桌钟',retroDeskClock],
 'Floppy Disc':['软盘',retroFloppy],
 Gramophone:['留声机',retroGramophone],
 'Music Player':['随身听',retroHandheld],
 'Music Disc':['黑胶唱片',retroRecord],
 Typewriter:['打字机',retroTypewriter],
};
function retroToy([id,label]){
 const split=label.lastIndexOf(' ');
 const [name,build]=retroModels[label.slice(0,split)];
 const color=label.slice(split+1);
 const [finish,prefix]=color==='White'?[ceramicIvory,'白']:[keepsakeFinishes.get(color),keepsakeColors.get(color)];
 return [id,[prefix+'色'+name,g=>build(g,finish)]];
}

