const gardenSoil=plastic('#866347');
const gardenFern=plastic('#75a166');
const gardenPetal=plastic('#f1e2aa');
const gardenWood=plastic('#a67c53');
const gardenSteel=plastic('#a6afaf');
const gardenInlay=plastic('#d98b6f');

function gardenTerraPot(g,finish,x=0,y=-.246,z=0){
 const body=lathe(g,[[0,-.133],[.157,-.133],[.173,-.111],[.218,.077],[.228,.105],[.224,.133],[.188,.137],[.191,.104],[0,.093]],finish);
 body.position.set(x,y,z);
 const dirt=disc(g,.184,.023,gardenSoil,x,y+.107,z);
 dirt.rotation.x=Math.PI/2;
 torus(g,.215,.018,gardenPetal,x,y+.107,z,32).rotation.x=Math.PI/2;
}

function gardenCactusToy(g,finish){
 gardenTerraPot(g,finish);
 sphere(g,.102,.265,.086,gardenFern,0,.061,0);
 for(const side of [-1,1]){
  const arm=sphere(g,.070,.146,.055,gardenFern,side*.109,.139+side*.035,.012);
  arm.rotation.z=-side*.45;
  for(const [x,y] of [[.021,.097],[.050,.019],[.022,.234],[.054,.158]]){
   sphere(g,.011,.017,.010,gardenPetal,x*side,y,.081);
  }
 }
 for(let i=0;i<5;i++){
  const a=i*Math.PI*.4;
  sphere(g,.036,.029,.019,gardenInlay,.043*Math.cos(a),.317+.025*Math.sin(a),.052);
 }
 g.rotation.set(.28,-.27,.11);
}

function gardenDaisyToy(g,finish){
 rod(g,[.015,-.368,0],[-.011,.223,0],.028,gardenFern);
 for(const side of [-1,1]){
  const leaf=sphere(g,.063,.135,.022,gardenFern,side*.071,-.187+side*.046,.012);
  leaf.rotation.z=-side*.81;
 }
 for(let i=0;i<9;i++){
  const a=i*Math.PI*2/9;
  const petal=sphere(g,.053,.106,.036,finish,Math.cos(a)*.118,.236+Math.sin(a)*.118,0);
  petal.rotation.z=a-Math.PI*.5;
 }
 sphere(g,.082,.082,.059,paradeGold,0,.236,.008);
 for(let i=0;i<8;i++){
  const a=i*Math.PI*.25;
  sphere(g,.010,.010,.008,gardenPetal,.043*Math.cos(a),.236+.043*Math.sin(a),.060);
 }
 g.rotation.set(.26,-.25,.45);
}

function gardenGnomeToy(g,finish){
 lathe(g,[[0,-.325],[.142,-.323],[.169,-.288],[.191,-.180],[.164,-.051],[.092,.010],[0,.024]],finish);
 sphere(g,.150,.132,.102,dollSkin,0,.059,.059);
 for(const side of [-1,1]){
  sphere(g,.035,.047,.037,dollSkin,side*.135,.032,.077);
  sphere(g,.071,.047,.072,gardenWood,side*.086,-.321,.045);
  sphere(g,.018,.022,.010,lacquerInk,side*.050,.086,.155);
 }
 sphere(g,.047,.039,.041,dollSkin,0,.025,.170);
 polygon(g,[[-.123,.008],[-.106,-.150],[0,-.258],[.111,-.156],[.121,.009]],.046,gardenPetal,.095);
 lathe(g,[[0,.090],[.166,.090],[.173,.117],[.141,.170],[.102,.239],[.059,.316],[.032,.386],[0,.411]],finish);
 torus(g,.158,.016,gardenPetal,0,.115,.004,30).rotation.x=Math.PI*.5;
 g.rotation.set(.23,-.29,.14);
}

function gardenPrunerToy(g,finish){
 const spat=[[-.110,-.018],[-.182,.301],[-.124,.360],[-.081,.301],[-.011,.039]];
 for(const side of [-1,1]){
  polygon(g,spat.map(([x,y])=>[x*side,y]),.062,gardenSteel,side*.035-.031);
  const handle=torus(g,.123,.038,finish,side*.131,-.226,-side*.029,30);
  handle.scale.set(.74,1.40,1);
  handle.rotation.z=side*.44;
  rod(g,[side*.131,-.140,-side*.029],[side*.030,-.013,-side*.029],.046,finish);
 }
 disc(g,.045,.102,gardenWood,0,-.017,.016);
 g.rotation.set(.20,-.29,.43);
}

function gardenMushroomToy(g,finish){
 lathe(g,[[0,-.337],[.129,-.336],[.141,-.288],[.122,-.207],[.101,-.133],[.116,-.031],[.172,.027],[0,.035]],gardenPetal);
 lathe(g,[[0,.348],[.077,.347],[.133,.331],[.217,.272],[.282,.188],[.316,.092],[.313,.029],[.257,.011],[.177,.024],[0,.033]],finish);
 for(const [x,y,z,w] of [[-.127,.243,.141,.046],[.047,.294,.131,.036],[.177,.183,.169,.051],[-.202,.132,.168,.039],[.023,.156,.255,.039]]){
  const dot=sphere(g,w,w,.016,gardenPetal,x,y,z);
  dot.rotation.set(-y*1.38,x*2.4,0);
 }
 torus(g,.105,.012,gardenInlay,0,-.168,.005,28).rotation.x=Math.PI/2;
 g.rotation.set(.30,-.31,.12);
}

function gardenShovelToy(g,finish){
 rod(g,[0,-.191,0],[0,.274,0],.050,gardenWood);
 const grip=torus(g,.095,.026,finish,0,.314,.005,24);
 grip.scale.y=.71;
 const scoop=[[-.126,.030],[-.130,-.218],[-.093,-.320],[0,-.374],[.091,-.324],[.135,-.222],[.125,.030]];
 polygon(g,scoop,.056,finish,-.016);
 moldedCurve(g,[[-.099,-.034,.043],[0,-.063,.064],[.100,-.034,.042]],.010,gardenSteel,15);
 box(g,.092,.118,.074,gardenSteel,0,.015,.007,.029);
 g.rotation.set(.26,-.32,.48);
}

function gardenWateringCanToy(g,finish){
 lathe(g,[[0,-.254],[.204,-.254],[.235,-.221],[.240,.188],[.200,.220],[.185,.189],[.191,-.211],[0,-.218]],finish);
 const handle=torus(g,.160,.033,finish,-.215,.043,0,32);
 handle.scale.set(.85,1.18,1);
 rod(g,[.168,-.159,0],[.353,.140,.035],.045,finish);
 sphere(g,.075,.056,.064,finish,.365,.147,.038).rotation.z=-.52;
 const top=torus(g,.170,.019,gardenPetal,0,.197,0,28);
 top.rotation.x=Math.PI/2;
 box(g,.175,.105,.018,gardenPetal,0,-.026,.243,.036);
 sphere(g,.029,.029,.012,gardenInlay,0,-.027,.257);
 g.rotation.set(.33,-.32,-.20);
}

function gardenWheelbarrowToy(g,finish){
 const tub=polygon(g,[[-.318,.102],[-.175,-.085],[.236,-.085],[.298,.120]],.305,finish,-.156);
 tub.rotation.z=.07;
 for(const side of [-1,1]){
  const z=side*.126;
  rod(g,[-.366,.089,z],[.283,-.139,z],.029,gardenWood);
  rod(g,[-.159,-.015,z],[-.212,-.249,z],.028,gardenWood);
  rod(g,[-.241,-.249,z],[.174,-.203,z],.020,gardenWood);
  box(g,.098,.061,.066,gardenPetal,-.363,.076,z,.023);
 }
 for(const [x,z] of [[.225,0]]){
  torus(g,.113,.041,lacquerInk,x,-.188,z,29);
  disc(g,.081,.099,gardenPetal,x,-.188,z);
  disc(g,.034,.116,gardenSteel,x,-.188,z);
 }
 g.rotation.set(.54,-.30,.04);
}

const gardenModels={
 Cactus:['仙人掌盆栽',gardenCactusToy],
 Daisy:['小雏菊',gardenDaisyToy],
 Dwarf:['花园小人摆件',gardenGnomeToy],
 'Garden Scissors':['园艺剪',gardenPrunerToy],
 Mushroom:['蘑菇摆件',gardenMushroomToy],
 Shovel:['园艺小铲',gardenShovelToy],
 'Watering Can':['浇花壶',gardenWateringCanToy],
 Wheelbarrow:['独轮小推车',gardenWheelbarrowToy],
};
function gardenToy([id,label]){
 const split=label.lastIndexOf(' ');
 const [name,build]=gardenModels[label.slice(0,split)];
 const color=label.slice(split+1);
 const finish=color==='White'?ceramicIvory:keepsakeFinishes.get(color);
 const prefix=color==='White'?'白':keepsakeColors.get(color);
 return [id,[prefix+'色'+name,g=>build(g,finish)]];
}

