const warmCeramicPan=plastic('#eeddb3');
const lowGrillFinish=plastic('#3c3a45');
const raisedGrillFinish=plastic('#5d5960');

function kitchenMarketPan(g,body,lining,grill=false){
 fryingPan(g,body);
 const interior=g.children.find(part=>part.material===cookwareInterior);
 interior.material=lining;
 for(const y of [-.175,-.09,0,.09,.175]){
  if(grill){
   const halfWidth=Math.sqrt(.23**2-y**2);
   rod(g,[-halfWidth,y,.005],[halfWidth,y,.005],.012,raisedGrillFinish);
  }else{
   const number=3+(y===0?2:0);
   for(let dot=0;dot<number;dot++){
    const x=(dot-(number-1)*.5)*.075+(y<0?.008:-.008);
    sphere(g,.008,.008,.003,colors.wood,x,y,-.014);
   }
  }
 }
 g.rotation.set(.23,-.14,-.27);
}

