const harborInk=plastic('#38434b');
const harborBrass=plastic('#dbb477');
const harborTwine=plastic('#ecd2a6');
const harborWood=plastic('#a27853');
const harborGlass=plastic('#689bb0');

function harborAnchor(g,finish){
 rod(g,[0,-.212,0],[0,.280,0],.048,finish);
 torus(g,.090,.032,harborBrass,0,.307,0,31);
 box(g,.364,.077,.098,finish,0,.128,0,.036);
 for(const side of [-1,1]){
  modeledAnchorArm(g,side,finish);
 }
 sphere(g,.074,.053,.072,harborBrass,0,-.231,.002);
 for(let i=0;i<4;i++)torus(g,.051,.012,harborTwine,0,-.092+i*.033,0,20).rotation.x=Math.PI/2;
 g.rotation.set(.29,-.23,-.36);
}

function modeledAnchorArm(g,side,finish){
 moldedCurve(g,[[0,-.217,0],[side*.154,-.212,0],[side*.260,-.159,0],[side*.311,-.073,0]],.047,finish,23);
 polygon(g,[[side*.224,-.127],[side*.319,.036],[side*.375,-.123]],.071,finish,-.034);
}

function harborBarrel(g,finish){
 const profile=[[0,-.328],[.230,-.328],[.249,-.296],[.272,-.196],[.290,-.026],[.274,.167],[.250,.279],[.224,.323],[0,.323]];
 lathe(g,profile,finish);
 for(const y of [-.248,.237]){
  torus(g,.255,.019,harborBrass,0,y,0,35).rotation.x=Math.PI/2;
  const hoop=lathe(g,[[.260,y-.022],[.262,y+.024]],harborInk);
  hoop.rotation.y=.03;
 }
 for(let i=0;i<9;i++){
  const a=i*Math.PI*2/9;
  const point=(r,y)=>[r*Math.cos(a),y,r*Math.sin(a)];
  moldedCurve(g,[point(.252,-.286),point(.293,-.015),point(.254,.281)],.006,harborWood,18);
 }
 disc(g,.198,.019,harborTwine,0,.330).rotation.x=Math.PI/2;
 g.rotation.set(.39,-.33,.18);
}

function harborBallLauncher(g,finish){
 box(g,.505,.154,.305,harborWood,0,-.173,0,.068);
 for(const side of [-1,1]){
  const wheel=disc(g,.116,.048,finish,side*.193,-.195,side*.176);
  wheel.rotation.y=side*.26;
  disc(g,.057,.060,harborBrass,side*.193,-.195,side*.180);
 }
 box(g,.336,.112,.235,finish,-.044,-.074,-.002,.045);
 const bell=lathe(g,[[0,-.213],[.073,-.213],[.103,-.031],[.149,.144],[.159,.223],[.138,.253],[.114,.247],[.113,.180],[.090,.097],[0,.085]],finish);
 bell.rotation.set(.16,0,-1.01);
 bell.position.set(.060,.041,0);
 const lip=torus(g,.146,.024,harborBrass,.247,.160,.030,34);
 lip.rotation.set(.12,.97,0);
 box(g,.950,.031,.028,harborTwine,0,-.342,0,.009);
 g.rotation.set(.26,-.29,-.03);
}

function harborCaptainHat(g,finish){
 const crown=[[-.362,-.142],[-.337,-.024],[-.217,.049],[-.163,.200],[-.034,.292],[.031,.292],[.163,.200],[.216,.049],[.339,-.023],[.363,-.142],[.236,-.213],[-.233,-.213]];
 polygon(g,crown,.181,finish,-.092);
 moldedCurve(g,[[-.316,-.102,.106],[-.201,-.143,.112],[0,-.167,.115],[.200,-.144,.110],[.318,-.101,.106]],.021,harborBrass,30);
 torus(g,.091,.012,harborBrass,0,.021,.109,36);
 for(const [x,y,l] of [[0,.022,.042],[-.044,.006,.023],[.044,.006,.023]]){
  sphere(g,l,.021,.010,harborTwine,x,y,.127);
 }
 g.rotation.set(.23,-.19,.16);
}

function harborParrot(g,finish){
 sphere(g,.179,.234,.144,finish,-.049,-.064,.011);
 sphere(g,.156,.137,.131,finish,.010,.191,.025);
 const beak=polygon(g,[[.114,.200],[.233,.188],[.226,.129],[.183,.080],[.149,.133]],.083,harborBrass,-.004);
 beak.rotation.y=-.25;
 for(const side of [-1,1]){
  const wing=sphere(g,.148,.095,.027,harborTwine,-.062,-.074,side*.135);
  wing.rotation.z=.94;
  sphere(g,.046,.042,.023,harborTwine,.066,.208,side*.133);
  sphere(g,.021,.020,.012,harborInk,.079,.207,side*.151);
 }
 for(const [offset,paint] of [[-.043,finish],[.038,harborBrass]]){
  const feather=sphere(g,.054,.182,.035,paint,-.136,-.211,.039+offset);
  feather.rotation.z=-.46;
 }
 for(const x of [-.040,.047])box(g,.087,.044,.057,harborBrass,x,-.281,.043,.017);
 g.rotation.set(.23,-.28,.05);
}

function harborPracticeSword(g,finish){
 const blade=[[-.070,-.182],[-.078,.213],[-.020,.340],[.092,.423],[.114,.374],[.061,.207],[.067,-.180]];
 polygon(g,blade,.083,finish,-.045);
 moldedCurve(g,[[.018,-.161,.041],[.002,.208,.042],[.079,.383,.041]],.010,harborTwine,24);
 const guard=torus(g,.111,.029,harborBrass,.059,-.254,.016,27);
 guard.scale.y=1.17;
 box(g,.093,.196,.079,harborWood,0,-.291,0,.034);
 for(const y of [-.244,-.290,-.336])box(g,.095,.015,.086,harborTwine,0,y,0,.005,false);
 sphere(g,.056,.047,.043,harborBrass,0,-.406,0);
 g.rotation.set(.25,-.27,.37);
}

function harborTelescope(g,finish){
 lathe(g,[[0,-.409],[.068,-.409],[.070,-.317],[.085,-.306],[.087,-.163],[.103,-.154],[.104,.015],[.139,.019],[.140,.300],[.154,.305],[.156,.391],[0,.391]],finish);
 for(const [r,y] of [[.071,-.359],[.087,-.198],[.105,-.026],[.141,.245],[.157,.382]]){
  torus(g,r,.013,harborBrass,0,y,0,30).rotation.x=Math.PI/2;
 }
 disc(g,.123,.020,harborGlass,0,.399,0).rotation.x=Math.PI/2;
 const grip=lathe(g,[[.140,.056],[.145,.062],[.145,.188],[.140,.194]],harborWood);
 grip.rotation.y=.18;
 g.rotation.set(.46,-.28,.58);
}

function harborWheel(g,finish){
 torus(g,.277,.048,finish,0,0,0,40);
 torus(g,.284,.016,harborTwine,0,0,.034,40);
 disc(g,.096,.107,harborBrass,0,0,0);
 for(let i=0;i<8;i++){
  const a=i*Math.PI/4,x=Math.cos(a),y=Math.sin(a);
  rod(g,[x*.080,y*.080,0],[x*.365,y*.365,0],.029,finish);
  const grip=sphere(g,.031,.063,.030,finish,x*.371,y*.371,0);
  grip.rotation.z=a-Math.PI*.5;
 }
 g.rotation.set(.25,-.23,.23);
}

const harborModels={
 Anchor:['船锚摆件',harborAnchor],
 Barrel:['木桶',harborBarrel],
 'Pirate Cannon':['弹球筒玩具',harborBallLauncher],
 'Pirate Hat':['船长帽',harborCaptainHat],
 'Pirate Parrot':['鹦鹉玩偶',harborParrot],
 'Pirate Sword':['弯柄泡棉剑',harborPracticeSword],
 'Pirate Telescope':['伸缩望远镜',harborTelescope],
 'Pirate Wheel':['木制船舵',harborWheel],
};
function harborToy([id,label]){
 const split=label.lastIndexOf(' ');
 const [name,build]=harborModels[label.slice(0,split)];
 const color=label.slice(split+1);
 return [id,[keepsakeColors.get(color)+'色'+name,g=>build(g,keepsakeFinishes.get(color))]];
}

