const barrelDot=new THREE.CircleGeometry(1,9);
const barrelLine=new THREE.PlaneGeometry(1,1);

function paintBarrelDecal(g,shape,paint,x,y,z,width,height,angle=0){
 const patch=add(g,shape.clone(),paint,x,y,z);
 patch.scale.set(width,height,1);
 patch.rotation.set(0,z<0?Math.PI:0,angle);
}

function orchardPaintedBarrel(g,finish,mark){
 harborBarrel(g,finish);
 for(const side of [-1,1]){
  const z=.294*side;
  for(const y of [-.248,.237])for(const x of [-.046,.046]){
   paintBarrelDecal(g,barrelDot,harborTwine,x,y,.278*side,.012,.012);
  }
  if(mark==='flower'){
   for(let petal=0;petal<5;petal++){
    const a=petal*Math.PI*.4;
    paintBarrelDecal(g,barrelDot,harborTwine,.045*Math.sin(a),.045*Math.cos(a),z,.019,.031,-a);
   }
   paintBarrelDecal(g,barrelDot,harborBrass,0,0,z,.023,.023);
  }else if(mark==='diamond'){
   paintBarrelDecal(g,barrelLine,harborWood,0,.004,z,.093,.093,Math.PI/4);
   paintBarrelDecal(g,barrelLine,harborTwine,0,.004,z*1.015,.045,.045,Math.PI/4);
  }else if(mark==='stripes'){
   for(const x of [-.039,.039]){
    paintBarrelDecal(g,barrelLine,harborTwine,x,0,z,.018,.113,-.43);
   }
  }else if(mark==='dots'){
   for(const x of [-.068,0,.068]){
    paintBarrelDecal(g,barrelDot,harborTwine,x,0,z,.021,.021);
   }
  }
 }
 const capRing=add(g,new THREE.RingGeometry(.093,.106,24),harborWood,0,.344,0);
 capRing.rotation.x=-Math.PI/2;
 const capLine=add(g,barrelLine.clone(),harborWood,0,.345,0);
 capLine.scale.set(.148,.013,1);
 capLine.rotation.x=-Math.PI/2;
}

