function vanityPerfume(g,finish){
 box(g,.541,.545,.289,finish,0,-.070,0,.123);
 box(g,.370,.353,.160,finish,0,-.055,.095,.109);
 for(const z of [-.160,.174]){
  box(g,.264,.217,.026,vanityIvory,0,-.074,z,.066);
  for(const [x,y,angle] of [[-.054,-.067,.68],[.055,-.067,-.68],[0,-.034,0]]){
   sphere(g,.030,.042,.009,vanityGold,x,y,z*1.15).rotation.z=angle;
  }
 }
 rod(g,[0,.197,0],[0,.280,0],.084,vanityGold);
 box(g,.248,.178,.236,vanityGold,0,.346,0,.052);
 box(g,.204,.036,.196,vanityIvory,0,.426,0,.047);
 g.rotation.set(.31,-.27,.15);
}

