const bakingMetal=new THREE.MeshStandardMaterial({color:'#b5bfc6',metalness:.51,roughness:.36});
const bakingGlass=new THREE.MeshPhysicalMaterial({color:'#83bcc1',roughness:.24,clearcoat:.48,transmission:.07});
