function bakingBlender(g,finish){
 box(g,.485,.225,.403,finish,0,-.256,0,.079);
 box(g,.456,.038,.381,bakingInk,0,-.360,0,.036);
 disc(g,.059,.037,bakingIvory,0,-.266,.205);
 box(g,.046,.024,.017,bakingInk,.014,-.266,.227,.007);
 const jug=lathe(g,[[0,-.145],[.153,-.145],[.166,-.120],[.184,.052],[.229,.238],[.231,.271],[.205,.265],[.200,.235],[.154,-.050],[0,-.050]],bakingGlass);
 jug.rotation.y=.08;
 lathe(g,[[.227,.258],[.241,.275],[.235,.309],[.217,.327],[0,.327]],finish);
 box(g,.147,.054,.132,bakingIvory,0,.346,0,.023);
 moldedCurve(g,[[.199,.206,0],[.306,.194,0],[.315,.054,0],[.262,-.073,0],[.166,-.081,0]],.023,bakingGlass,25);
 for(let i=0;i<4;i++)box(g,i%2?.047:.075,.010,.010,bakingIvory,-.067,-.041+i*.053,.168+i*.012,.003,false);
 g.rotation.set(.35,-.25,.15);
}

function bakingDuck(g,finish){
 sphere(g,.263,.153,.186,finish,-.062,-.170,0);
 sphere(g,.149,.157,.132,finish,.119,.012,.031);
 sphere(g,.095,.048,.073,duckBill,.216,-.040,.068);
 const cap=box(g,.248,.081,.222,bakingIvory,.107,.144,.020,.035);
 cap.rotation.z=.08;
 for(const [dx,dy] of [[-.085,.216],[0,.243],[.085,.209]])sphere(g,.084,.104,.096,bakingIvory,.105+dx,dy,.021);
 sphere(g,.024,.029,.013,bakingInk,.149,.024,.151);
 sphere(g,.009,.010,.006,bakingIvory,.157,.035,.162);
 sphere(g,.149,.070,.047,finish,-.048,-.145,.159).rotation.z=.22;
 moldedCurve(g,[[.017,-.072,.123],[.062,-.095,.150],[.138,-.096,.140],[.191,-.082,.095]],.022,paradeRed,18);
 g.rotation.set(.24,-.28,-.16);
}

function bakingGrater(g,finish){
 polygon(g,[[-.263,-.274],[-.194,.237],[.194,.237],[.263,-.274]],.239,bakingMetal,-.119);
 box(g,.530,.064,.279,finish,0,-.266,0,.023);
 moldedCurve(g,[[-.130,.222,0],[-.116,.335,.006],[0,.373,.008],[.117,.335,.006],[.130,.222,0]],.035,finish,23);
 for(const side of [-1,1]){
  for(let row=0;row<4;row++)for(let col=0;col<4;col++){
   const x=(col-1.5+(row%2)*.27)*.083;
   const y=-.170+row*.103;
   const z=side*.134;
   sphere(g,.017,.021,.005,bakingInk,x,y,z);
   const rim=torus(g,.020,.006,bakingIvory,x,y+.007,z*1.025,15);
   rim.scale.x=.89;
  }
 }
 g.rotation.set(.33,-.34,.23);
}

function bakingMicrowave(g,finish){
 box(g,.758,.453,.478,finish,0,0,0,.070);
 box(g,.529,.335,.067,bakingIvory,-.090,-.003,.235,.034);
 box(g,.439,.248,.033,bakingInk,-.096,-.003,.272,.026);
 box(g,.388,.207,.017,bakingGlass,-.112,.002,.291,.020);
 const shine=box(g,.215,.015,.008,bakingIvory,-.132,.055,.304,.005,false);
 shine.rotation.z=.23;
 box(g,.026,.154,.036,finish,.098,-.003,.296,.010);
 box(g,.094,.050,.021,bakingInk,.282,.107,.246,.013);
 for(const y of [-.028,-.114])disc(g,.035,.027,bakingIvory,.281,y,.251);
 for(let i=0;i<5;i++)box(g,.017,.043,.009,bakingInk,.155+i*.039,.100,-.246,.004,false);
 g.rotation.set(.45,-.38,.09);
}

function bakingMitt(g,finish){
 const outline=[[-.157,-.366],[-.243,-.137],[-.268,.064],[-.216,.213],[-.130,.301],[-.038,.321],[.050,.278],[.092,.178],[.151,.194],[.207,.145],[.210,.065],[.145,-.089],[.135,-.348]];
 polygon(g,outline,.127,finish,-.063);
 box(g,.291,.105,.152,bakingSeam,-.005,-.295,0,.030);
 torus(g,.049,.012,bakingSeam,-.140,-.365,.012,21);
 for(const z of [-.079,.079]){
  for(const [x,y] of [[-.143,.164],[-.054,.215],[-.16,.057],[-.065,.101],[.018,.139],[-.146,-.056],[-.054,-.016],[.030,.027],[-.125,-.161],[-.036,-.124],[.038,-.077]]){
   rod(g,[x-.009,y-.011,z],[x+.009,y+.011,z],.006,bakingIvory);
   rod(g,[x-.009,y+.011,z],[x+.009,y-.011,z],.006,bakingIvory);
  }
 }
 g.rotation.set(.26,-.25,.29);
}

function bakingRollingPin(g,finish){
 lathe(g,[[0,-.268],[.087,-.268],[.121,-.234],[.122,.234],[.087,.268],[0,.268]],bakingWood);
 for(const side of [-1,1]){
  rod(g,[0,side*.247,0],[0,side*.402,0],.040,bakingMetal);
  const handle=sphere(g,.062,.125,.062,finish,0,side*.362,0);
  handle.rotation.z=side*.07;
  torus(g,.103,.009,finish,0,side*.231,0,25).rotation.x=Math.PI/2;
 }
 const grain=plastic('#ad8050');
 for(let i=0;i<4;i++){
  const a=(i+.18)*Math.PI*.5;
  rod(g,[.121*Math.cos(a),-.186,.121*Math.sin(a)],[.121*Math.cos(a),.186,.121*Math.sin(a)],.0035,grain);
 }
 g.rotation.set(.21,-.22,-.61);
}

function bakingWhisk(g,finish){
 rod(g,[0,-.394,0],[0,-.075,0],.065,finish);
 sphere(g,.066,.059,.065,finish,0,-.391,0);
 sphere(g,.069,.055,.068,bakingMetal,0,-.068,0);
 for(let i=0;i<5;i++){
  const a=i*Math.PI/5;
  const p=(r,y)=>[r*Math.cos(a),y,r*Math.sin(a)];
  moldedCurve(g,[p(0,-.054),p(.098,.103),p(.115,.245),p(0,.363),p(-.115,.245),p(-.098,.103),p(0,-.054)],.0095,bakingMetal,29);
 }
 g.rotation.set(.23,-.35,.43);
}

function bakingPlate(g,finish,color){
 const dish=lathe(g,[[0,-.060],[.295,-.060],[.337,-.038],[.399,.015],[.416,.053],[.403,.076],[.379,.075],[.346,.040],[.276,.002],[0,.002]],bakingIvory);
 dish.rotation.x=Math.PI/2;
 torus(g,.381,.026,finish,0,0,.059,42);
 torus(g,.307,.008,finish,0,0,.040,39);
 const petals=color==='Colorful'?[paradeRed,toyPink,paradeBlue,gardenGreen,paradeGold,toyPurple]:[finish];
 for(let i=0;i<6;i++){
  const a=i*Math.PI/3;
  sphere(g,.036,.070,.007,petals[i%petals.length],.109*Math.cos(a),.109*Math.sin(a),.010).rotation.z=a-Math.PI*.5;
 }
 disc(g,.034,.012,bakingSeam,0,0,.018);
 g.rotation.set(.31,-.28,.11);
}

function bakingToy([id,label]){
 const split=label.lastIndexOf(' ');
 const family=label.slice(0,split),color=label.slice(split+1);
 const alternate={White:[bakingIvory,'白色'],Colorful:[paradeBlue,'彩绘']};
 const [finish,prefix]=alternate[color]??[keepsakeFinishes.get(color),keepsakeColors.get(color)+'色'];
 const variants={
  Blender:['料理机',bakingBlender],
  'Chef Duck':['厨师小鸭',bakingDuck],
  Grater:['擦丝器',bakingGrater],
  Microwave:['微波炉',bakingMicrowave],
  'Oven Mitts':['隔热手套',bakingMitt],
  'Rolling Pin':['擀面杖',bakingRollingPin],
  Whisk:['打蛋器',bakingWhisk],
  Plate:['餐盘',bakingPlate],
 };
 const [name,build]=variants[family];
 return [id,[prefix+name,g=>build(g,finish,color)]];
}

