function stripedCandyCane(g,paint){
 const points=[[0,-.378,0],[0,-.019,0],[.005,.215,0],[-.059,.330,0],[-.207,.328,0],[-.261,.224,0]];
 const curve=new THREE.CatmullRomCurve3(points.map(point=>new THREE.Vector3(...point)));
 add(g,new THREE.TubeGeometry(curve,40,.064,12,false),colors.cream);
 for(let i=0;i<10;i++){
  const point=curve.getPointAt((i+.35)/10);
  const tangent=curve.getTangentAt((i+.35)/10);
  const red=torus(g,.062,.010,paint,point.x,point.y,point.z,22);
  red.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),tangent);
 }
 for(const index of [0,5])sphere(g,.063,.063,.063,colors.cream,...points[index]);
 g.rotation.set(.22,-.27,-.49);
}

