const catBengalFur=plastic('#c88954');
const catBengalMark=plastic('#774a35');
const catBritishFur=plastic('#a499bc');
const catPersianFur=plastic('#ad7659');
const catSiameseFur=plastic('#e7c99f');
const catSiamesePoint=plastic('#765344');
const catFurCream=plastic('#f7e8cc');
const catNose=plastic('#c37576');
const catEyes=plastic('#414052');
const catCushion=plastic('#f2b7bb');
const catBasketBody=plastic('#d88495');
const catScratcherRope=plastic('#d3af80');

function homeCatFigure(g,{body,face=body,mark=body,profile='round'}){
 const slender=profile==='siamese'||profile==='bengal';
 const fluffy=profile==='persian';
 const belly=slender?.161:.202;
 const head=fluffy?.242:slender?.167:.208;
 const elevation=slender?.157:.132;
 sphere(g,belly,.241,.163,body,0,-.109,-.021);
 sphere(g,head,fluffy?.171:.153,.153,face,0,elevation,.044);
 sphere(g,.119,.150,.030,catFurCream,0,-.105,.138);
 for(const side of [-1,1]){
  const earX=side*head*.65;
  polygon(g,[[earX-side*.076,elevation+.067],[earX+side*.018,elevation+.240],[earX+side*.090,elevation+.073]],.085,face,.018);
  polygon(g,[[earX-side*.037,elevation+.087],[earX+side*.019,elevation+.194],[earX+side*.065,elevation+.083]],.012,catNose,.104);
  sphere(g,.023,.033,.018,catEyes,side*head*.51,elevation+.013,.181);
  sphere(g,.007,.009,.006,catFurCream,side*head*.51+.006,elevation+.023,.197);
  sphere(g,fluffy?.089:.054,.044,.044,face,side*.049,elevation-.049,.180);
  sphere(g,.068,.051,.092,face,side*.085,-.298,.112);
  if(profile==='bengal'){
   for(const [x,y,z] of [[.119,-.053,.102],[.145,-.119,.107],[.097,-.174,.138],[.132,-.201,.088]]){
    const spot=sphere(g,.023,.015,.008,mark,side*x,y,z);
    spot.rotation.y=side*.49;
   }
  }
  if(fluffy){
   for(let i=0;i<3;i++)sphere(g,.068,.077,.052,body,side*(.138+i*.028),.041-i*.047,.055);
  }
 }
 sphere(g,.028,.017,.017,catNose,0,elevation-.034,.222);
 moldedCurve(g,[[.081,-.198,-.097],[.244,-.240,-.080],[.292,-.175,-.033],[.271,-.072,.019]],fluffy?.049:.033,mark,20);
 g.rotation.set(.29,-.31,.12);
}

const catBellBallGreen=plastic('#8bae79');
const catBellBallGreenStripe=plastic('#b1cd8f');

function greenBellBall(g,body=catBellBallGreen,stripe=catBellBallGreenStripe){
 sphere(g,.285,.279,.285,body);
 for(const angle of [-.62,.62]){
  torus(g,.282,.014,stripe,0,0,0,26).rotation.set(.38,angle,.39);
 }
 disc(g,.052,.010,softGold,.009,.050,.279);
 box(g,.053,.012,.009,catEyes,.010,.050,.285,.006,false);
}

function pinkCatBasket(g,body=catBasketBody,cushion=catCushion){
 lathe(g,[[0,-.188],[.237,-.188],[.301,-.161],[.337,-.108],[.357,.031],[.345,.093],[.309,.094],[.284,-.081],[0,-.081]],body);
 sphere(g,.271,.068,.268,cushion,0,-.062,0);
 for(const y of [-.106,-.057,-.007,.043,.092]){
  const radius=.327+(y+.106)*.154;
  torus(g,radius,.014,cushion,0,y,0,32).rotation.x=Math.PI*.5;
 }
 g.rotation.set(.39,-.25,.12);
}

const blueCatBowlGlaze=plastic('#78a9c4');

function blueCatBowl(g,glaze=blueCatBowlGlaze){
 lathe(g,[[0,-.134],[.277,-.134],[.381,-.113],[.369,-.063],[.310,.075],[.300,.093],[.271,.096],[.243,.007],[.222,-.053],[0,-.053]],glaze);
 torus(g,.291,.012,catFurCream,0,.091,0,32).rotation.x=Math.PI*.5;
 sphere(g,.036,.023,.009,catFurCream,0,-.051,.358);
 for(const x of [-.034,0,.034])sphere(g,.014,.012,.009,catFurCream,x,-.018,.341);
 g.rotation.x=.34;
}

function redScratcher(g,paint=paradeRed){
 box(g,.585,.095,.421,paint,0,-.252,0,.043,false);
 rod(g,[0,-.208,0],[0,.273,0],.103,catScratcherRope);
 for(let i=0;i<14;i++){
  torus(g,.103,.011,bakingIvory,0,-.199+i*.034,0,20).rotation.x=Math.PI*.5;
 }
 box(g,.311,.077,.300,paint,0,.316,0,.036,false);
 rod(g,[.132,.292,.099],[.198,.112,.142],.009,catScratcherRope);
 sphere(g,.047,.048,.046,catCushion,.197,.103,.142);
 g.rotation.set(.24,-.31,.11);
}

