const jamJarLabel=plastic('#eee0bc');
const jamJarSeal=plastic('#f6d7a6');

const jamJarPrints = new Map();
function jamJarPrint(name,filling){
 if(!jamJarPrints.has(name)){
  jamJarPrints.set(name,packagingInk('#f6e6bb',ctx=>{
   const ink='#'+filling.color.getHexString();
   ctx.fillStyle=ink;
   ctx.fillRect(11,15,170,27);
   ctx.fillRect(11,214,170,25);
   ctx.fillStyle='#664332';
   ctx.textAlign='center';
   ctx.font='bold 37px "Hiragino Sans GB","Heiti SC",sans-serif';
   printInk(ctx,name,96,104);
   circleInk(ctx,93,155,29,ink);
   circleInk(ctx,115,128,11,'#6e945c');
  }));
 }
 return jamJarPrints.get(name);
}
function fruitJamJar(g,{filling,cap,leaf=gardenGreen,name}){
 lathe(g,[[0,-.325],[.211,-.325],[.250,-.299],[.259,-.255],[.259,.095],[.239,.160],[.178,.208],[.180,.252],[0,.252]],filling);
 lathe(g,[[0,.215],[.204,.215],[.224,.233],[.224,.292],[.204,.312],[0,.312]],cap);
 for(let i=0;i<14;i++){
  const a=Math.PI*2*i/14;
  const x=.220*Math.cos(a),z=.220*Math.sin(a);
  rod(g,[x,.240,z],[x,.281,z],.006,jamJarSeal);
 }
 if(name){
  const print=jamJarPrint(name,filling);
  for(const side of [-1,1])packageFace(g,.29,.209,0,-.052,side*.261,print,side<0);
 }
 for(const side of name?[]:[-1,1]){
  box(g,.273,.205,.031,jamJarLabel,0,-.053,side*.235,.026,false);
  sphere(g,.050,.048,.013,filling,0,-.045,side*.253);
  sphere(g,.024,.010,.009,leaf,.027,-.008,side*.254).rotation.z=.49;
 }
 g.rotation.set(.29,-.32,.12);
}

