const toyCoffeeInk=new WeakMap();
function toyCoffeeBag(g,finish){
 box(g,.656,.803,.275,finish,0,-.008,0,.11);
 box(g,.623,.084,.164,finish,0,.407,0,.025);
 box(g,.623,.078,.202,finish,0,-.407,0,.035);
 let ink=toyCoffeeInk.get(finish);
 if(!ink){
  ink=packagingInk('#f6dfb5',ctx=>{
   ctx.fillStyle='#713d26';
   ctx.textAlign='center';
   ctx.font='bold 32px "PingFang SC","Microsoft YaHei",sans-serif';
   printInk(ctx,'咖啡豆',96,64);
   ctx.font='bold 17px sans-serif';
   printInk(ctx,'COFFEE',96,88);
   ctx.fillRect(27,105,138,3);
   ctx.beginPath();
   ctx.ellipse(95,160,36,25,-.45,0,Math.PI*2);
   ctx.fill();
   ctx.strokeStyle='#f6dfb5';
   ctx.lineWidth=3;
   ctx.beginPath();ctx.moveTo(71,178);ctx.quadraticCurveTo(110,153,122,140);ctx.stroke();
   ctx.fillRect(34,211,124,3);
  });
  toyCoffeeInk.set(finish,ink);
 }
 packageFace(g,.426,.568,0,-.008,.14,ink);
 packageFace(g,.426,.568,0,-.008,-.14,ink,true);
}

