const peachTeaCeramic=new THREE.MeshPhysicalMaterial({
 color:'#d6919e',roughness:.35,clearcoat:.38,clearcoatRoughness:.29,
});
const peachTeaPetal=plastic('#f8e3bd');
const peachTeaCenter=plastic('#b96a62');

function peachBlossomTeapot(g){
 nurseryTeapot(g,peachTeaCeramic);
 torus(g,.208,.010,peachTeaCenter,0,.193,0,28).rotation.x=Math.PI/2;
 for(const face of [-1,1]){
  for(let i=0;i<5;i++){
   const angle=i*Math.PI*2/5;
   const petal=sphere(g,.018,.040,.008,peachTeaPetal,.052*Math.cos(angle),-.113+.052*Math.sin(angle),face*.319);
   petal.rotation.z=angle-Math.PI*.5;
  }
  sphere(g,.019,.020,.011,peachTeaCenter,0,-.113,face*.330);
 }
}

const lionLacquer1391=plastic('#c96456');
const lionLacquer1386=plastic('#74a6c8');
const lionLacquer1385=plastic('#72a79c');
function lacquerLionToy(g,finish){
 craftLionToy(g,finish);
 for(const side of [-1,1]){
  moldedCurve(g,[[side*.047,.205,.204],[side*.102,.233,.214],[side*.167,.210,.199]],.012,porcelainGold,12);
  sphere(g,.021,.024,.011,paradeRed,side*.181,.087,.203);
 }
 torus(g,.036,.008,porcelainGold,0,-.120,.172,17);
 sphere(g,.022,.025,.014,porcelainGold,0,-.135,.180);
}
