const campStoveSlate=plastic('#555563');
const campStoveBlue=plastic('#6899af');
const campStoveRed=plastic('#bf685b');

function compactCampStove(g,finish){
 campingToyStove(g,finish);
 for(const z of [-.095,-.053,-.011,.031,.073]){
  box(g,.083,.008,.014,campsiteHardware,.233,-.021,z,.003,false);
 }
 for(const x of [.135,.268])sphere(g,.008,.008,.005,campsiteAluminum,x,-.151,.235);
 torus(g,.054,.006,campsiteAluminum,.202,-.084,.270,22);
}

const outdoorFlaskBlue=plastic('#6996ac');
const outdoorFlaskGreen=plastic('#8ba679');
const outdoorFlaskGold=plastic('#d2a654');

function outdoorFlask(g,finish){
 campingToyFlask(g,finish);
 torus(g,.182,.008,campsiteHardware,0,.270,0,30).rotation.x=Math.PI/2;
 for(let index=0;index<12;index++){
  const angle=index*Math.PI/6;
  const x=.181*Math.cos(angle);
  const z=.181*Math.sin(angle);
  rod(g,[x,.295,z],[x,.354,z],.005,campsiteHardware);
 }
}
