const enamelMicrowaveBlue=plastic('#699caf');
const enamelMicrowaveOrange=plastic('#cb8a58');
const enamelMicrowaveRed=plastic('#be685c');

function enamelMicrowave(g,finish){
 bakingMicrowave(g,finish);
 for(const [x,y] of [[.256,.115],[.279,.115],[.306,.115],[.279,.100]]){
  box(g,.012,.006,.007,retroKeys,x,y,.260,.002,false);
 }
 for(const y of [-.028,-.114]){
  torus(g,.032,.005,bakingMetal,.281,y,.270,19);
  box(g,.007,.018,.007,finish,.281,y+.003,.272,.002,false);
 }
 for(const x of [-.231,.236])box(g,.081,.033,.131,bakingInk,x,-.234,-.116,.013,false);
}

const dinnerwareBlue=plastic('#78adbf');
const dinnerwareGreen=plastic('#82ac87');
const dinnerwarePink=plastic('#cf99a2');
const dinnerwareIvory=plastic('#f5e4c0');
const dinnerwareLeaf=plastic('#9eb795');

function flowerDinnerPlate(g,finish,color){
 bakingPlate(g,finish,color);
 torus(g,.333,.004,finish,0,0,.049,42);
 for(let index=0;index<6;index++){
  const angle=index*Math.PI/3+Math.PI/6;
  const point=(r,a,z)=>[Math.cos(a)*r,Math.sin(a)*r,z];
  moldedCurve(g,[point(.197,angle-.08,.009),point(.227,angle,.008),point(.252,angle+.12,.007)],.004,dinnerwareLeaf,8);
  sphere(g,.020,.007,.004,dinnerwareLeaf,...point(.226,angle+.04,.012)).rotation.z=angle+.43;
 }
}
