const candyChipGreen=plastic('#8db282');

function sugarChipDoughnut(g,icing){
 const pastry=torus(g,.284,.139,toastCrust,0,0,0,36);
 pastry.scale.z=.80;
 const sugarCoat=torus(g,.285,.123,icing,0,0,.072,36);
 sugarCoat.scale.z=.56;
 const chips=[candyChipPink,candyChipLemon,candyChipGreen];
 for(let index=0;index<13;index++){
  const theta=index*Math.PI*2/13;
  const radius=.283+.045*Math.sin(index*3.2);
  const x=radius*Math.cos(theta),y=radius*Math.sin(theta);
  sphere(g,.019,.007,.006,chips[index%chips.length],x,y,.139).rotation.z=theta+.51;
 }
 g.rotation.set(.36,-.25,.17);
}
