const mittThread=plastic('#f6e8ca');
const mittCuff=plastic('#eaddb9');
const winterMittOutline=[[-.157,-.366],[-.243,-.137],[-.268,.064],[-.216,.213],[-.130,.301],[-.038,.321],[.050,.278],[.092,.178],[.151,.194],[.207,.145],[.210,.065],[.145,-.089],[.135,-.348]];

function quiltedWinterMitt(g,color){
 const fabric=new THREE.MeshStandardMaterial({color,roughness:.73});
 const piping=new THREE.MeshStandardMaterial({color:new THREE.Color(color).multiplyScalar(.78),roughness:.66});
 polygon(g,winterMittOutline,.127,fabric,-.063);
 box(g,.293,.109,.154,mittCuff,-.005,-.295,0,.030);
 torus(g,.049,.012,piping,-.140,-.365,.012,21);
 for(const z of [-.079,.079]){
  const seam=winterMittOutline.map(([x,y])=>[x*.88,y*.88,z]);
  moldedCurve(g,[...seam,seam[0],seam[1]],.0047,piping,48);
  for(const [x,y] of [[-.141,.16],[-.058,.213],[-.172,.054],[-.075,.112],[.014,.146],[-.15,-.058],[-.057,-.005],[.027,.048],[-.121,-.162],[-.037,-.111],[.048,-.058]]){
   rod(g,[x-.013,y-.008,z],[x+.013,y+.008,z],.0037,mittThread);
   rod(g,[x-.009,y+.013,z],[x+.009,y-.013,z],.0037,mittThread);
  }
  for(let i=0;i<7;i++){
   const x=-.109+i*.035;
   rod(g,[x,-.293,z],[x+.017,-.293,z],.0031,piping);
  }
 }
 g.rotation.set(.26,-.25,.29);
}

const teaSetCobalt=plastic('#37699f');
const teaSetCustard=plastic('#fff0cc');
const teaSetPollen=plastic('#edb347');
const teaSetGlaze={roughness:.31,clearcoat:.40,clearcoatRoughness:.24};

function winterTeaService(g,color,paint){
 const finish=new THREE.MeshPhysicalMaterial({color,...teaSetGlaze});
 nurseryTeapot(g,finish);
 torus(g,.209,.009,paint,0,.182,0,36).rotation.x=Math.PI/2;
 torus(g,.236,.012,paint,0,-.264,0,36).rotation.x=Math.PI/2;
 for(const side of [-1,1]){
  for(let i=0;i<5;i++){
   const angle=(i*.4+.5)*Math.PI;
   const petal=sphere(g,.017,.030,.007,paint,.044*Math.cos(angle),-.048+.044*Math.sin(angle),side*.322);
   petal.rotation.z=angle-Math.PI*.5;
  }
  sphere(g,.018,.018,.008,teaSetPollen,0,-.048,side*.331);
  for(const x of [-.103,.103]){
   const leaf=sphere(g,.024,.011,.007,paint,x,-.111,side*.312);
   leaf.rotation.z=x<0?.4:-.4;
  }
 }
}
