const deskCover=plastic('#355e9c');
const deskCoverRibbon=plastic('#7bbcc3');
const deskRuler=plastic('#68bdd0');
const deskRulerMarks=plastic('#234e62');
const deskPencil=plastic('#6f9de0');

function exerciseNotebook(g){
 spiralNotebook(g,deskCover);
 for(const z of [-.105,.105]){
  box(g,.066,.690,.012,deskCoverRibbon,.219,0,z,.018);
  box(g,.095,.038,.014,deskCoverRibbon,.178,-.244,z,.010);
 }
 for(const y of [-.278,-.207,-.136,.012,.082,.224,.292]){
  box(g,.011,.007,.125,teaSetCustard,.325,y,0,.004,false);
 }
}

function ruledDeskRuler(g){
 box(g,.235,.935,.070,deskRuler,0,0,0,.026);
 for(const z of [-.044,.044]){
  box(g,.027,.820,.009,teaSetCustard,-.074,0,z,.008,false);
  for(let i=0;i<17;i++){
   const width=i%4===0?.091:i%2===0?.063:.043;
   box(g,width,.010,.008,deskRulerMarks,.097-width*.5,-.404+i*.049,z,.003,false);
  }
 }
 g.rotation.set(.16,-.18,-.29);
}
