const snackOrange=plastic('#e17b37');
const snackMango=plastic('#edba42');
const snackBlue=plastic('#4b91b7');
const snackPaper=plastic('#fff1cd');

function breakfastJuicePack(g,ink,mango){
 juiceCarton(g,ink);
 for(const side of [-1,1]){
  const z=side*.224;
  if(mango){
   sphere(g,.088,.106,.013,ink,-.017,.035,z).rotation.z=-.40;
   sphere(g,.064,.082,.011,snackPaper,-.028,.036,z*1.068).rotation.z=-.40;
   sphere(g,.049,.023,.010,colors.green,.036,.122,z).rotation.z=.46;
  }else{
   disc(g,.093,.014,snackPaper,-.026,.032,z);
   disc(g,.075,.015,ink,-.026,.032,z*1.071);
   for(let i=0;i<6;i++){
    const a=i*Math.PI/3;
    rod(g,[-.026,.032,z*1.105],[-.026+.068*Math.cos(a),.032+.068*Math.sin(a),z*1.105],.006,snackPaper);
   }
  }
 }
}

function breakfastMilkPack(g){
 milkCarton(g,snackBlue);
 for(const side of [-1,1]){
  box(g,.380,.024,.011,snackBlue,0,-.104,side*.225,.008,false);
  box(g,.316,.009,.008,snackBlue,0,-.149,side*.226,.004,false);
 }
}
