const playgroundBallFinishes = new Map();
function playgroundPracticeBall(g,paint,ink){
 let finish=playgroundBallFinishes.get(paint);
 if(!finish){
  finish=plastic(paint);
  finish.roughness=.61;
  if(typeof document!=='undefined'){
   const canvas=document.createElement('canvas');
   canvas.width=512;
   canvas.height=256;
   const ctx=canvas.getContext('2d');
   ctx.fillStyle=paint;
   ctx.fillRect(0,0,512,256);
   ctx.fillStyle=ink;
   ctx.textAlign='center';
   for(const x of [128,384]){
    ctx.font='bold 23px sans-serif';
    printInk(ctx,'练习球',x,128);
    ctx.font='bold 12px sans-serif';
    printInk(ctx,'40+',x,144);
   }
   finish.map=new THREE.CanvasTexture(canvas);
   finish.map.colorSpace=THREE.SRGBColorSpace;
   finish.color.set(0xffffff);
  }
  playgroundBallFinishes.set(paint,finish);
 }
 add(g,new THREE.SphereGeometry(.49,32,24),finish);
}
