const morningJugBlue=plastic('#328da6');
const morningJugGreen=plastic('#468963');
const morningJugOrange=plastic('#bd5f36');
const morningJugPink=plastic('#ba6489');
const morningJugGold=plastic('#e8be62');
const morningJugMark=packagingInk('#f8ecd4',ctx=>{
 ctx.fillStyle='#6f3e2a';
 ctx.textAlign='center';
 ctx.font='bold 76px "PingFang SC","Microsoft YaHei",sans-serif';
 printInk(ctx,'热',96,106);
 printInk(ctx,'饮',96,212);
 ctx.strokeStyle='#a98a4d';
 ctx.lineWidth=5;
 ctx.strokeRect(10,10,172,236);
});

function morningJug(g,finish){
 outdoorFlask(g,finish);
 box(g,.147,.202,.023,campsiteCloth,0,-.058,.233,.028,false);
 packageFace(g,.122,.175,0,-.058,.258,morningJugMark);
 box(g,.147,.202,.023,campsiteCloth,0,-.058,-.224,.028,false);
 packageFace(g,.122,.175,0,-.058,-.241,morningJugMark,true);
 for(const y of [-.246,.186])torus(g,.219,.009,porcelainGold,0,y,0,36).rotation.x=Math.PI/2;
}
