const courtyardRadioOrange=plastic('#b65731');
const courtyardRadioGold=plastic('#e8bb55');
const courtyardRadioPlate=packagingInk('#f1deb3',ctx=>{
 ctx.textAlign='center';
 ctx.fillStyle='#644231';
 ctx.save();
 ctx.scale(1,2.4);
 ctx.font='bold 46px "PingFang SC","Microsoft YaHei",sans-serif';
 printInk(ctx,'收音机',96,70);
 ctx.restore();
});

function courtyardPocketRadio(g,finish){
 pocketRadio(g,finish);
 packageFace(g,.224,.059,-.144,-.192,.202,courtyardRadioPlate);
 box(g,.462,.192,.025,slate,.012,-.032,-.165,.032,false);
 for(let index=0;index<5;index++){
  const x=(index-2)*.061;
  box(g,.018,.058,.011,colors.dark,x,-.016,-.188,.008,false);
 }
 box(g,.208,.026,.012,instrumentCream,.012,-.095,-.184,.006,false);
}
