const classPencilLacquer=['#2d78ad','#4a8258','#74767b','#c76f35','#b94044','#daa945'].map(plastic);
function lacquerClassPencil(g,index){
 const finish=classPencilLacquer[index];
 craftPencil(g,finish);
 for(const y of [-.304,-.265]){
  lathe(g,[[.083,y],[.089,y+.003],[.089,y+.016],[.081,y+.017]],porcelainGold);
 }
 lathe(g,[[.027,.434],[.009,.469],[0,.480]],finish);
}

const neighborhoodReadingCovers=[
 ['水浒','浪花','#2475af'],
 ['西游','祥云','#a46145'],
 ['成语','竹叶','#5b914f'],
 ['唐诗','远山','#b85938'],
 ['儿歌','花朵','#bf6684'],
].map(([title,ornament,color])=>packagingInk('#fae9c7',ctx=>{
 ctx.strokeStyle=color;
 ctx.lineWidth=7;
 ctx.strokeRect(11,11,170,234);
 ctx.fillStyle=color;
 ctx.textAlign='center';
 ctx.font='bold 63px "PingFang SC","Microsoft YaHei",sans-serif';
 printInk(ctx,title,96,104);
 ctx.fillRect(38,124,116,3);
 ctx.font='34px "PingFang SC","Microsoft YaHei",sans-serif';
 printInk(ctx,ornament,96,181);
}));

function neighborhoodBook(g,index){
 hardbackBook(g,bookFinishes[index]);
 const cover=neighborhoodReadingCovers[index];
 box(g,.430,.515,.019,bookPages,.041,-.029,.153,.021,false);
 packageFace(g,.405,.489,.041,-.029,.181,cover);
 packageFace(g,.228,.159,.037,.217,-.163,cover,true);
 g.rotation.set(.22,-.26,-.09);
}
