function illustratedBookStallVolume(g,index){
 const [,title,cover,ink]=bookStallCovers[index];
 hardbackBook(g,bookFinishes[index]);
 if(!bookStallInk.has(index)){
  const front=packagingInk(cover,ctx=>{
   ctx.strokeStyle=ink;
   ctx.lineWidth=3;
   ctx.strokeRect(9,10,174,236);
   ctx.fillStyle=ink;
   ctx.textAlign='center';
   ctx.font='bold 33px "Hiragino Sans GB","Heiti SC",sans-serif';
   printInk(ctx,title,96,65);
   bookStallIllustrations[index](ctx,ink,cover);
  });
  const back=packagingInk(cover,ctx=>{
   ctx.fillStyle=ink;
   ctx.fillRect(25,31,142,3);
   ctx.font='bold 22px "Hiragino Sans GB","Heiti SC",sans-serif';
   ctx.textAlign='center';
   printInk(ctx,'社区读书角',96,63);
   for(let line=0;line<7;line++)ctx.fillRect(26,108+line*13,140-(line%3)*22,2.5);
   ctx.fillRect(104,205,59,16);
  });
  bookStallInk.set(index,[front,back]);
 }
 const [front,back]=bookStallInk.get(index);
 packageFace(g,.613,.861,.02,0,.163,front);
 packageFace(g,.613,.861,.02,0,-.163,back,true);
}

function bookStallVolume(id){
 const index=id-279;
 return [bookStallCovers[index][0],g=>illustratedBookStallVolume(g,index)];
}
