const kitchenRollingGrain=plastic('#a36d4a');
const kitchenRollingKnot=plastic('#bb824c');

function homeRollingPin(g,finish){
 bakingRollingPin(g,finish);
 for(const x of [-.061,.061]){
  moldedCurve(g,[[x,-.157,.105],[x*.72,-.088,.115],[x*.52,.014,.120],[x*.74,.096,.114],[x,.170,.105]],.004,kitchenRollingGrain);
 }
 torus(g,.038,.004,kitchenRollingKnot,.008,.060,.120,24).scale.set(.49,1.18,1);
 for(const y of [-.206,.206])torus(g,.122,.007,kitchenRollingGrain,0,y,0,30).rotation.x=Math.PI/2;
}

function homeKitchenWhisk(g){
 rod(g,[0,-.392,0],[0,-.068,0],.080,cargoGray);
 sphere(g,.080,.060,.080,cargoGray,0,-.391,0);
 sphere(g,.079,.054,.079,bakingMetal,0,-.069,0);
 rod(g,[0,-.072,0],[0,.174,0],.032,bakingMetal);
 sphere(g,.032,.034,.032,bakingMetal,0,.170,0);
 for(let i=0;i<5;i++){
  const angle=i*Math.PI/5;
  const point=(radius,y)=>[radius*Math.cos(angle),y,radius*Math.sin(angle)];
  moldedCurve(g,[point(0,-.054),point(.103,.105),point(.125,.245),point(0,.363),
   point(-.125,.245),point(-.103,.105),point(0,-.054)],.013,bakingMetal,29);
 }
 for(const y of [-.335,-.290,-.245]){
  torus(g,.080,.006,kitchenRollingKnot,0,y,0,28).rotation.x=Math.PI/2;
 }
 g.rotation.set(.23,-.35,.43);
}
