const neighborhoodCassettePaint=[
 ['蓝色','#377ebe','#eef0df'],['棕色','#995d42','#f6e3bd'],
 ['绿色','#4d9568','#e9edc5'],['橙色','#cd7834','#fff0c9'],
 ['粉色','#c96690','#fbe1dc'],['紫色','#805ba9','#f1e4f8'],
 ['红色','#b93f4c','#fbe8cf'],['黄色','#ba8d31','#fff0c4'],
];
const neighborhoodCassetteLabels = new Map();

function neighborhoodCassette(g,index){
 const [,color,paper]=neighborhoodCassettePaint[index];
 const cache=neighborhoodCassetteLabels.get(index)??[
  plastic(color),
  ...['A','B'].map(side=>packagingInk(paper,ctx=>{
   ctx.fillStyle=color;
   ctx.fillRect(8,18,38,220);
   ctx.fillRect(56,66,124,14);
   ctx.fillRect(56,176,124,8);
   ctx.fillStyle=paper;
   ctx.font='bold 46px sans-serif';
   ctx.textAlign='center';
   printInk(ctx,side,27,143);
   ctx.fillStyle='#423746';
   ctx.font='bold 23px "Hiragino Sans GB","Heiti SC",sans-serif';
   printInk(ctx,'街角录音社',118,129);
   ctx.font='bold 15px sans-serif';
   printInk(ctx,'SIDE '+side+' · 60 MIN',116,163);
  })),
 ];
 neighborhoodCassetteLabels.set(index,cache);
 const [body,front,back]=cache;
 retroCassette(g,body);
 packageFace(g,.594,.117,0,.117,.112,front);
 packageFace(g,.594,.117,0,.117,-.112,back,true);
}

function repairShopTape(id){
 const index=id-1479;
 return [neighborhoodCassettePaint[index][0]+'磁带',g=>neighborhoodCassette(g,index)];
}

const repairRadioFrequency=packagingInk('#e7d9b7',ctx=>{
 ctx.fillStyle='#465d71';
 ctx.font='bold 100px sans-serif';
 ctx.textAlign='center';
 printInk(ctx,'FM 88–108',96,162,172);
});

function workshopPocketRadio(g,finish,index){
 pocketRadio(g,finish);
 const needleX=.166+index*.038;
 box(g,.011,.044,.013,paradeRed,needleX,.095,.218,.003,false);
 packageFace(g,.209,.041,.221,.029,.188,repairRadioFrequency);
 torus(g,.081,.006,breakfastSteel,.217,-.094,.228,28);
 box(g,.093,.033,.056,colors.dark,.226,.231,.018,.012);
 box(g,.053,.013,.043,instrumentCream,.237,.252,.018,.006);
}
