const stationeryNotebookCovers = new WeakMap();
function stationeryShopNotebook(g,finish){
 spiralNotebook(g,finish);
 let ink=stationeryNotebookCovers.get(finish);
 if(!ink){
  ink=packagingInk('#f9e9bd',ctx=>{
   ctx.strokeStyle='#7b4b33';
   ctx.lineWidth=4;
   ctx.strokeRect(10,10,172,236);
   ctx.fillStyle='#7b4b33';
   ctx.textAlign='center';
   ctx.font='bold 36px "PingFang SC","Microsoft YaHei",sans-serif';
   printInk(ctx,'作业本',96,83);
   ctx.font='22px "PingFang SC","Microsoft YaHei",sans-serif';
   printInk(ctx,'姓名',46,144);
   printInk(ctx,'班级',46,193);
   ctx.fillRect(75,145,84,3);
   ctx.fillRect(75,194,84,3);
  });
  stationeryNotebookCovers.set(finish,ink);
 }
 box(g,.303,.291,.011,colors.cream,.054,.062,.121,.014,false);
 box(g,.303,.291,.011,colors.cream,.054,.062,-.1,.014,false);
 packageFace(g,.265,.252,.054,.062,.151,ink);
 packageFace(g,.265,.252,.054,.062,-.108,ink,true);
}
