const courtyardSoapPalette=[
 ['青柚皂','#5296ab','#f9efd0','#326372'],
 ['桃花皂','#d7869e','#fff0de','#884953'],
 ['薰衣草皂','#947fc3','#f8ecf6','#614887'],
 ['山茶皂','#ba5353','#fff0d9','#7a3c3c'],
].map(([name,body,paper,ink])=>({
 body:plastic(body),
 label:packagingInk(paper,ctx=>{
  ctx.strokeStyle=ink;
  ctx.lineWidth=7;
  ctx.beginPath();
  ctx.ellipse(96,129,85,111,0,0,Math.PI*2);
  ctx.stroke();
  ctx.textAlign='center';
  ctx.fillStyle=ink;
  ctx.font=`bold ${name.length>3?38:49}px "PingFang SC","Microsoft YaHei",sans-serif`;
  printInk(ctx,name,96,130);
  ctx.fillRect(64,151,64,4);
 }),
}));
function courtyardSoapBar(g,index){
 const {body,label}=courtyardSoapPalette[index];
 lavenderSoapBar(g,body);
 packageFace(g,.298,.176,0,-.042,.142,label);
 packageFace(g,.276,.162,0,-.042,-.129,label,true);
}
