const tailorSilk=['#5b91ae','#628c6a','#d08383','#a17bb2','#ba5457','#d6aa58'].map(plastic);
const tailorWood=plastic('#d5ad73');
const tailorLinen=plastic('#ebd9a5');
const tailorInk=plastic('#705239');
const tailorSteel=new THREE.MeshStandardMaterial({color:'#bcc5c9',roughness:.38,metalness:.48});
const tailorTapeLabels=tailorSilk.map((_,index)=>packagingInk('#f5e7c4',ctx=>{
 ctx.strokeStyle=['#376281','#466744','#aa5b58','#765188','#974447','#a2773c'][index];
 ctx.lineWidth=9;
 ctx.arc(96,128,69,0,Math.PI*2);
 ctx.stroke();
 ctx.fillStyle=ctx.strokeStyle;
 ctx.font='bold 50px "PingFang SC",sans-serif';
 ctx.textAlign='center';
 printInk(ctx,'软尺',96,146);
}));

function tailorThreadSpool(g,index){
 const silk=tailorSilk[index];
 lathe(g,[[0,-.329],[.221,-.329],[.252,-.305],[.252,-.249],[.204,-.228],
  [.182,-.178],[.182,.180],[.207,.226],[.251,.249],[.251,.302],[.221,.324],
  [.056,.324],[.044,.301],[.044,-.301],[.056,-.329],[0,-.329]],tailorWood);
 lathe(g,[[.174,-.227],[.195,-.225],[.214,-.192],[.218,-.129],[.218,.129],
  [.214,.192],[.195,.225],[.174,.227]],silk);
 for(let i=0;i<11;i++){
  const ring=torus(g,.218,.006,silk,0,-.174+i*.034,0,30);
  ring.rotation.x=Math.PI/2;
 }
 const loose=[[.214,-.071,0],[.218,-.095,.055],[.234,-.121,.097],[.239,-.154,.121],[.213,-.186,.117]];
 moldedCurve(g,loose,.009,silk,18);
 g.rotation.set(.31,-.26,.29);
}

function tailorTapeMeasure(g,index){
 const cover=tailorSilk[index];
 disc(g,.282,.181,cover,-.063,0,0);
 for(const side of [-1,1]){
  torus(g,.243,.011,tailorWood,-.063,0,side*.085,34);
  packageFace(g,.320,.333,-.063,0,side*.094,tailorTapeLabels[index],side<0);
 }
 const tape=box(g,.345,.103,.027,tailorLinen,.217,-.089,.011,.013,false);
 tape.rotation.z=.15;
 for(let j=0;j<7;j++){
  const x=.085+j*.039;
  box(g,.008,j%3===0?.060:.034,.006,tailorInk,x,-.087+(x-.217)*.15,.027,.002,false);
 }
 box(g,.036,.104,.041,tailorSteel,.391,-.062,.008,.015,false).rotation.z=.15;
 g.rotation.set(.22,-.29,.25);
}

function tailorPinCushion(g,index){
 const silk=tailorSilk[index];
 lathe(g,[[0,-.235],[.208,-.235],[.234,-.211],[.249,-.135],[.247,-.091],[0,-.091]],tailorWood);
 sphere(g,.263,.155,.261,silk,0,-.044,0);
 for(let i=0;i<8;i++){
  const a=i*Math.PI/4;
  const point=(radius,y)=>[radius*Math.cos(a),y,radius*Math.sin(a)];
  moldedCurve(g,[point(.086,.104),point(.183,.069),point(.239,.012),point(.258,-.065)],.005,tailorLinen,13);
 }
 for(const [x,z,lean] of [[-.102,-.043,-.042],[.052,.034,.063],[.126,-.031,.036]]){
  rod(g,[x,.061,z],[x+lean,.238,z+.021],.012,tailorSteel);
  sphere(g,.028,.027,.028,tailorSilk[(index+3)%tailorSilk.length],x+lean,.239,z+.021);
 }
 g.rotation.set(.77,-.24,.16);
}

function tailorThimble(g,index){
 const paint=tailorSilk[index];
 lathe(g,[[.222,-.252],[.245,-.244],[.241,-.200],[.193,.132],[.148,.207],[.075,.237],
  [0,.240],[0,.193],[.076,.187],[.142,.154],[.179,-.192],[.204,-.233]],paint);
 torus(g,.230,.016,tailorSteel,0,-.229,0,34).rotation.x=Math.PI/2;
 for(let row=0;row<4;row++){
  const y=-.126+row*.067,r=.225-row*.009;
  for(let i=0;i<10;i++){
   const a=(i+row*.5)*Math.PI*.2;
   sphere(g,.010,.010,.010,tailorSteel,r*Math.cos(a),y,r*Math.sin(a));
  }
 }
 g.rotation.set(.55,-.24,.18);
}
