const grainCloth=plastic('#d4c099');
const grainLinen=plastic('#e0cfaa');
const grainWood=plastic('#ae8758');
const grainBurlapPaint=[
 [plastic('#aa8d63'),plastic('#f1dfb5'),'粳米','#5d7955'],
 [plastic('#b27769'),plastic('#a6524b'),'红豆','#a44c40'],
 [plastic('#8fa16a'),plastic('#778e49'),'绿豆','#527949'],
 [plastic('#c1a56b'),plastic('#e0ad4d'),'小米','#96733d'],
];

function grainBag(g,index){
 const [cloth,grain,word,inkColor]=grainBurlapPaint[index];
 const sack=lathe(g,[[0,-.286],[.164,-.286],[.224,-.260],[.250,-.170],
  [.244,.019],[.210,.147],[.223,.190],[.187,.217],[0,.217]],cloth);
 sack.scale.z=.8;
 const rim=torus(g,.202,.024,grainLinen,0,.203,0,32);
 rim.rotation.x=Math.PI/2;rim.scale.y=.82;
 sphere(g,.174,.046,.143,grain,0,.232,0);
 for(let i=0;i<17;i++){
  const a=i*2.399,r=.031+.129*Math.sqrt(i/16);
  const kernel=sphere(g,index===1?.017:.012,.008,index===0?.023:.014,
   i%3===0?grainLinen:grain,r*Math.cos(a),.264-r*.07,r*.80*Math.sin(a));
  kernel.rotation.y=a;
 }
 for(const side of [-1,1]){
  for(let j=0;j<6;j++){
   const y=(j-3)*.038;
   box(g,.006,.018,.015,grainLinen,.141*side,y,.151,.003,false);
  }
 }
 const stamp=packagingInk('#efdfb9',ctx=>{
  ctx.fillStyle=inkColor;ctx.strokeStyle=inkColor;ctx.lineWidth=6;
  ctx.strokeRect(13,18,166,220);ctx.textAlign='center';
  ctx.font='bold 83px "PingFang SC",sans-serif';
  printInk(ctx,word[0],96,109);printInk(ctx,word[1],96,201);
 });
 packageFace(g,.184,.215,0,-.050,.210,stamp);
 g.rotation.set(.42,-.27,.19+index*.03);
}

function grainScoop(g){
 const blade=lathe(g,[[0,-.097],[.145,-.097],[.178,-.059],[.211,.030],[.209,.050],
  [.185,.045],[.155,-.043],[0,-.051]],grainCloth);
 blade.scale.z=.77;
 box(g,.102,.074,.423,grainWood,0,-.001,.277,.035);
 for(const x of [-.024,.019]){
  box(g,.011,.012,.259,grainCloth,x,.037,.305,.004,false);
 }
 g.rotation.set(.78,-.32,.38);
}

function grainJar(g){
 const jar=lathe(g,[[0,-.271],[.182,-.271],[.218,-.243],[.224,-.167],[.211,.099],
  [.184,.153],[.167,.158],[0,.158]],plastic('#e1c69b'));
 jar.scale.z=.88;
 lathe(g,[[0,.136],[.185,.136],[.213,.163],[.210,.219],[.182,.244],[0,.244]],grainWood).scale.z=.88;
 const stamp=packagingInk('#faf0cf',ctx=>{
  ctx.fillStyle='#634463';ctx.textAlign='center';ctx.font='bold 63px "PingFang SC",sans-serif';
  printInk(ctx,'香',96,103);printInk(ctx,'米',96,188);
 });
 packageFace(g,.176,.230,0,-.061,.207,stamp);
 g.rotation.set(.38,-.29,-.17);
}

function grainBasket(g){
 const woven=plastic('#b69664');
 const basket=lathe(g,[[0,-.153],[.220,-.153],[.267,-.099],[.296,.061],[.318,.111],
  [.286,.114],[.251,.035],[.205,-.090],[0,-.100]],woven);
 basket.scale.z=.84;
 for(const [y,r] of [[-.115,.254],[-.067,.272],[-.018,.283],[.031,.293],[.077,.307],[.106,.311]]){
  const strand=torus(g,r,.008,grainLinen,0,y,0,34);
  strand.rotation.x=Math.PI/2;strand.scale.y=.84;
 }
 g.rotation.set(1.03,-.26,-.23);
}

function grainScale(g){
 const shell=plastic('#7d9b6c');
 box(g,.475,.259,.330,shell,0,-.154,0,.056);
 disc(g,.089,.023,grainLinen,0,-.134,.179);
 rod(g,[0,-.138,.194],[.043,-.091,.194],.006,grainWood);
 lathe(g,[[0,-.003],[.218,-.003],[.255,.022],[.296,.111],[.279,.128],
  [.243,.071],[.206,.038],[0,.038]],grainLinen);
 g.rotation.set(.64,-.24,.15);
}

function grainReceiptTin(g){
 const red=plastic('#b66c56');
 box(g,.551,.197,.376,red,0,-.027,0,.061);
 const rim=box(g,.572,.046,.398,grainLinen,0,.081,0,.041);
 rim.rotation.y=-.015;
 const label=packagingInk('#efe0b5',ctx=>{
  ctx.fillStyle='#9b5a4c';ctx.textAlign='center';ctx.font='bold 62px "PingFang SC",sans-serif';
  printInk(ctx,'粮',96,106);printInk(ctx,'票',96,187);
 });
 packageFace(g,.165,.192,0,.113,0,label).rotation.x=-Math.PI/2;
 g.rotation.set(.60,-.25,-.16);
}
