const kitchenCeladon=plastic('#91a680');
const kitchenVermilion=plastic('#bc594d');
const kitchenCream=plastic('#f3e4c1');
const kitchenBrass=plastic('#c6a26d');
const kitchenWood=plastic('#a88358');
const kitchenSteel=plastic('#98aeb1');
const kitchenCharcoal=plastic('#465b67');

function neighborhoodKitchenBowl(g){
 lathe(g,[[0,-.230],[.117,-.230],[.147,-.199],[.239,-.117],[.298,-.018],
  [.310,.129],[.284,.126],[.263,.005],[.213,-.089],[.115,-.164],[0,-.163]],kitchenCeladon);
 for(const [y,r] of [[-.169,.185],[.124,.307]]){
  torus(g,r,.013,kitchenCream,0,y,0,36).rotation.x=Math.PI/2;
 }
 g.rotation.set(.88,-.24,.17);
}

function neighborhoodKitchenPot(g){
 lathe(g,[[0,-.250],[.198,-.250],[.262,-.212],[.283,-.124],[.282,.135],
  [.261,.170],[.229,.160],[0,.160]],kitchenVermilion);
 lathe(g,[[0,.165],[.192,.165],[.263,.149],[.281,.174],[.269,.201],[.196,.238],
  [.054,.252],[0,.250]],kitchenCream);
 const knob=lathe(g,[[0,.246],[.053,.246],[.045,.285],[.071,.303],[.057,.321],[0,.321]],kitchenCharcoal);
 knob.rotation.y=.24;
 for(const side of [-1,1]){
  moldedCurve(g,[[side*.262,.092,-.075],[side*.362,.083,-.044],
   [side*.365,.058,.075],[side*.266,.034,.089]],.025,kitchenCharcoal,16);
 }
 g.rotation.set(.61,-.23,.20);
}

function neighborhoodKitchenLadle(g,strainer=false){
 const finish=strainer?kitchenBrass:kitchenSteel;
 const scoop=lathe(g,[[0,-.076],[.102,-.076],[.161,-.050],[.198,.019],[.181,.028],
  [.145,-.020],[.097,-.048],[0,-.049]],finish);
 scoop.position.y=-.272;
 scoop.rotation.x=Math.PI/2;
 rod(g,[0,-.147,0],[0,.339,0],.024,finish);
 box(g,.085,.190,.073,kitchenWood,0,.286,0,.031);
 if(strainer){
  for(let i=0;i<11;i++){
   const a=i*2.399,r=.036+.104*Math.sqrt(i/10);
   disc(g,.011,.004,kitchenCharcoal,r*Math.cos(a),-.273+r*Math.sin(a),.074);
  }
 }
 g.rotation.set(.35,-.33,-.47);
}

function neighborhoodRollingPin(g){
 lathe(g,[[0,-.376],[.051,-.376],[.063,-.348],[.060,-.271],[.125,-.242],
  [.133,-.220],[.133,.220],[.125,.242],[.060,.269],[.063,.345],[.051,.374],[0,.374]],kitchenWood);
 for(const y of [-.205,.205]){
  const ring=torus(g,.132,.007,kitchenBrass,0,y,0,26);
  ring.rotation.x=Math.PI/2;
 }
 g.rotation.set(.45,-.25,-.42);
}

function neighborhoodChopstickBucket(g){
 lathe(g,[[0,-.315],[.205,-.315],[.227,-.281],[.216,.107],[.191,.125],
  [.172,.109],[.181,-.270],[0,-.270]],kitchenCeladon);
 for(const [x,z,lean] of [[-.116,.074,-.19],[.103,.067,.17],[.045,-.098,.15],
  [-.059,-.094,-.09]]){
  box(g,.029,.671,.025,kitchenWood,x,.037,z,.008,false).rotation.z=lean;
 }
 for(const y of [-.256,.093]){
  torus(g,.216,.010,kitchenCream,0,y,0,32).rotation.x=Math.PI/2;
 }
 g.rotation.set(.42,-.27,.19);
}

function neighborhoodOilCruet(g){
 lathe(g,[[0,-.302],[.153,-.302],[.192,-.274],[.198,-.156],[.179,.056],
  [.129,.158],[.095,.184],[.084,.250],[0,.250]],kitchenBrass);
 lathe(g,[[0,.237],[.103,.237],[.107,.262],[.077,.295],[.053,.328],[.035,.345],[0,.345]],kitchenCharcoal);
 const stamp=packagingInk('#f1dfb7',ctx=>{
  ctx.fillStyle='#967042';ctx.font='bold 122px "PingFang SC",sans-serif';
  ctx.textAlign='center';printInk(ctx,'油',96,158);
 });
 packageFace(g,.163,.187,0,-.070,.194,stamp).rotation.x=-.07;
 g.rotation.set(.36,-.29,-.15);
}

function neighborhoodBeveledBoard(g,finish=kitchenWood){
 box(g,.593,.826,.123,finish,0,-.013,0,.114);
 const collar=torus(g,.062,.010,kitchenCharcoal,0,.260,.077,22);
 collar.scale.y=.74;
 for(const x of [-.171,-.071,.060,.160]){
  moldedCurve(g,[[x,-.332,.061],[x-.025,-.202,.064],[x+.007,-.035,.064],
   [x-.017,.145,.064]],.0036,kitchenBrass,15);
 }
 g.rotation.set(.29,-.30,.25);
}

function neighborhoodKitchenKnife(g){
 polygon(g,[[-.207,-.088],[-.202,.289],[-.172,.352],[.202,.349],[.226,.288],[.191,-.084]],
  .064,kitchenSteel,-.033);
 box(g,.129,.258,.105,kitchenWood,0,-.218,0,.028);
 for(const y of [-.169,-.276])disc(g,.016,.007,kitchenBrass,0,y,.058);
 g.rotation.set(.31,-.26,-.31);
}
