const teaRiceBowlGlazes=['#5e8cb3','#71a27b','#cf7d94','#9d7baf','#efe8d8'].map(plastic);
const teaRiceCracker=plastic('#eac083');
const teaRiceCrackerToast=plastic('#c28c55');

function teaRiceCrackers(g,index){
 const glaze=teaRiceBowlGlazes[index];
 lathe(g,[[0,-.188],[.198,-.188],[.253,-.150],[.315,-.040],[.339,.065],
  [.310,.074],[.272,-.030],[.221,-.119],[0,-.128]],glaze);
 torus(g,.322,.020,glaze,0,.065,0,30).rotation.x=Math.PI/2;
 for(const [x,y,z,tilt] of [[-.148,.007,.024,.22],[.133,.038,.061,-.25],[.004,.074,-.103,.18]]){
  const cracker=box(g,.222,.106,.158,teaRiceCracker,x,y,z,.043);
  cracker.rotation.y=tilt;
  for(const [dx,dz] of [[-.055,.020],[.011,-.020],[.054,.033]]) {
   sphere(g,.012,.003,.008,teaRiceCrackerToast,x+dx,y+.054,z+dz);
  }
 }
 g.rotation.set(1.0,-.15,.12);
}


