function deskCoffeeBean(g){
 const bean=sphere(g,.30,.400,.175,pastryNutBrown,0,0,0);
 bean.rotation.z=-.28;
 moldedCurve(g,[[-.106,-.302,.123],[.053,-.202,.165],[.025,-.053,.177],
  [-.077,.085,.171],[-.034,.239,.142],[.102,.310,.105]],.018,pastryCoffee,30);
 g.rotation.set(.23,-.31,-.14);
}

function deskBaristaDuck(g,finish){
 marketEnamelDuck(g,pastryCream,paradeGold);
 const apron=box(g,.207,.221,.037,finish,.008,-.104,.198,.034);
 apron.rotation.x=-.26;
 for(const x of [-.074,.074])rod(g,[x,-.119,.210],[x*.70,.045,.215],.019,finish);
 const beret=disc(g,.138,.065,finish,0,.337,0);
 beret.rotation.x=Math.PI*.42;
}

function deskEarWarmers(g,finish){
 const arc=add(g,new THREE.TorusGeometry(.238,.035,10,32,Math.PI),finish,0,-.026,0);
 arc.scale.y=1.3;
 for(const x of [-.241,.241]){
  sphere(g,.089,.128,.095,finish,x,-.120,0);
  sphere(g,.062,.089,.079,pastryCream,x*.83,-.125,.034);
 }
 g.rotation.set(.14,-.28,-.24);
}

function deskPanpipe(g,finish){
 for(let i=0;i<7;i++){
  const x=(i-3)*.087,h=.580-i*.051,y=.262-h/2;
  box(g,.070,h,.081,finish,x,y,0,.027,false);
  disc(g,.022,.015,pastryCoffee,x,.267,0).rotation.x=Math.PI/2;
 }
 for(const y of [.064,.140])box(g,.639,.035,.093,pastryBrass,0,y,.006,.012);
 g.rotation.set(.22,-.15,.26);
}

function deskPiano(g,finish){
 box(g,.700,.318,.334,finish,0,.117,-.100,.056);
 box(g,.685,.119,.334,finish,0,-.086,.067,.037);
 for(let i=0;i<8;i++)box(g,.076,.042,.237,ceramicIvory,(i-3.5)*.081,-.013,.173,.009,false);
 for(const i of [-3,-2,0,1,2])box(g,.041,.032,.132,dialGlass,i*.081,.018,.120,.006,false);
 for(const x of [-.266,.266]){
  box(g,.078,.242,.079,finish,x,-.247,-.097,.014,false);
  box(g,.094,.039,.235,finish,x,-.369,-.027,.013,false);
 }
 g.rotation.set(.30,-.33,.12);
}

function deskSmallBoat(g,finish,rescue){
 const length=rescue?.389:.432;
 sphere(g,.217,.087,length,finish,0,-.072,0);
 if(rescue){
  const rim=[[0,.017,.345],[-.167,.017,.224],[-.170,.018,-.224],[0,.017,-.344],
   [.170,.018,-.224],[.167,.017,.224],[0,.017,.345]];
  moldedCurve(g,rim,.049,finish,30);
  for(const z of [-.141,.052])box(g,.297,.034,.072,pastryCream,0,.029,z,.015,false);
 }else{
  sphere(g,.144,.078,.304,ceramicIvory,0,-.011,0);
  box(g,.126,.083,.400,dialGlass,0,.068,-.083,.038);
  rod(g,[0,.022,.196],[0,.183,.116],.028,finish);
  rod(g,[-.122,.187,.117],[.122,.187,.117],.023,dialGlass);
 }
 g.rotation.set(.23,-.32,.11);
}

function deskRedSnorkel(g){
 summerSnorkel(g,paradeRed);
 const guide=new THREE.Path();
 guide.moveTo(-.152,.338);
 guide.lineTo(-.152,-.185);
 guide.bezierCurveTo(-.152,-.358,.182,-.415,.182,-.208);
 guide.lineTo(.182,-.105);
 const points=guide.getPoints(18).map(({x,y})=>new THREE.Vector3(x,y,0));
 const curve=new THREE.CatmullRomCurve3(points);
 add(g,new THREE.TubeGeometry(curve,30,.088,10,false),paperclipPickMaterial);
 g.userData.hasPickAssist=true;
}


