const campaignProps=new Map([
 ['orange-carton',g=>juiceCarton(g,colors.orange)],
 ['berry-carton',g=>juiceCarton(g,plastic('#b64e70'))],
 ['green-soda',g=>{sodaBottle(g,'#679751');g.scale.x=1.25;g.scale.z=1.25;}],
 ['milk-drink',milkDrink],
 ['drink-ice',drinkIce],
 ['watercolor-tray',watercolorTray],
 ['blue-paint-tube',paintTube],
 ['enamel-kettle',kitchenKettle],
 ...['L','O','V','E'].map((letter,i)=>['letter-tile-'+letter,g=>letterTile(g,letterDrawings[i],[colors.red,colors.blue,colors.green,colors.orange][i])]),
 ...[1,2,3,4,5,6,10,12,15].map(number=>['pool-ball-'+number,g=>numberedPoolBall(g,587+number)]),
 ['racket-blue',g=>tennisRacket(g,racketPaints[0])],
 ['racket-green',g=>tennisRacket(g,racketPaints[1])],
 ['pingpong-paddle',g=>{pingPongPaddle(g);g.rotation.y=Math.PI;}],
 ['badminton-racket',badmintonRacket],
 ['training-bat',practiceBat],
 ['baseball-practice',baseball],
 ['sport-pingpong-ball',g=>{pingPongBall(g,'#ed9b43');g.scale.setScalar(.70);}],
 ['record-berry',g=>recordDisc(g,plastic('#bc475c'),plastic('#f0aa65'),1)],
 ['record-mint',g=>recordDisc(g,plastic('#3c896c'),plastic('#e09549'),2)],
 ['record-blue',g=>recordDisc(g,plastic('#4c66a3'),plastic('#bc6d9b'),3)],
 ['toy-bus',toyBus],
 ['toy-locomotive',g=>{toyLocomotive(g,trainPaint,colors.red,tire);g.rotation.set(.35,-.25,0);}],
 ['mung-bean-ice-pop',g=>icePop(g,plastic('#94ae65'),plastic('#d9d694'),plastic('#759653'))],
 ['red-bean-ice-pop',g=>icePop(g,plastic('#b77467'),plastic('#eec49a'),plastic('#94565c'))],
 ['play-block-red',g=>playBlock(g,plastic('#ce584e'),plastic('#edb680'),1)],
 ['play-block-blue',g=>playBlock(g,plastic('#4798b1'),plastic('#acd0c7'),2)],
 ['play-block-gold',g=>playBlock(g,plastic('#dc9a34'),plastic('#f4d877'),3)],
]);

export const hasCampaignProp=key=>campaignProps.has(key);

export function makeCampaignProp(key){
 const builder=campaignProps.get(key);
 if(!builder)return null;
 if(!templates.has(key))templates.set(key,build(0,builder));
 return templates.get(key).clone(true);
}

export function buildHouseholdClassic(kind,options){
 const {paint,high,label}=options;
 switch(kind){
  case 'rotary-phone':return build(898,g=>rotaryTelephone(g,paint,options));
  case 'mantel-clock':return build(1492,g=>mantelClock(g,paint,options));
  case 'matchbox':return build(1441,g=>campingMatchbox(g,1441,label,high));
  default:throw new Error('Unknown household classic '+kind);
 }
}
